// HET MOUNTPUNT VAN DE BEWERKLAAG IN DE LEESCOMPONENTEN.
//
// Het probleem dat deze module oplost. De ghosts en de actiestroken horen ÍN de
// kaart-, regel- en voorwaardecomponenten te staan — dat is de hele winst van
// fase C taak 9d: elke actie staat waar zijn resultaat landt. Maar die
// componenten zitten in de LEESCHUNK, en de bewerklaag mag daar niet in
// terechtkomen (spec §1, harde eis; `stores/lazy-grens.test.ts` bewaakt hem).
// Een gewone `import { KaartRegelGhost } from '../bewerk/…'` in `regels.tsx`
// zou de hele laag de instap in trekken.
//
// Vandaar een OMKERING: de leescomponent zet een LEGE PLEK neer (`<Haak>`), en
// de bewerklaag vult die bij het laden. De leeschunk kent alleen deze module —
// zeven optionele functies en een signaal — en géén byte van de bewerklaag.
//
// WAT DIT NIET IS. Geen event-bus en geen dependency-injectie-container: het is
// één signaal met een vaste, getypeerde vorm, in dezelfde geest als
// `registreerOnthuller` in de weergavestore. Wie een plek toevoegt, breidt
// `BewerkHaken` uit en zet er een `<Haak>` neer; de typecheck wijst de rest aan.
//
// GEEN LADER MEER. Deze module hééft de bewerklaag ooit zelf binnengehaald, als
// tijdelijke vorm zolang er nog geen bewerkchrome was. Die chrome is er
// (`ui/app/bewerkstand.tsx` laadt de laag via de bevestigflow), en daarmee is
// dit weer wat het hoort te zijn: een SIGNAAL, geen laadwortel. De rest van dat
// verhaal staat onderaan.
import { createSignal } from 'solid-js';
import type { JSX } from 'solid-js';
import { weergave } from '../../stores/weergave.js';
import type { Policy, Regel } from '../kaart/kaart.jsx';
import type { RegelSoort } from './chip.jsx';

/** Wat een KAART-plek van de bewerklaag nodig heeft. */
export interface KaartHaakCtx {
  pol: Policy;
  /** De kaartsoort, voor het silhouet van de ghost-kaart. */
  soort?: string;
  /** SEAM NAAR lane-velden: de stand van het ✎ op de kaartkop — het inline
   *  titelveld is van die lane. Blijft hij weg, dan draagt de kopstrook drie
   *  iconen in plaats van vier (dat is wat `ActieStrook` doet met een sleutel
   *  die de aanroeper weglaat), en niet een ✎ dat niets opent. De vorm is
   *  `IcoonStand` uit `ui/bewerk/strook.tsx`; hij staat hier als `unknown`
   *  zodat deze LEESchunk-module geen bewerkcomponent hoeft te importeren. */
  titelBewerk?: unknown;
  /** WELKE SOORTEN deze toevoegplek aanbiedt (eigenaarsbesluit 9 sep 2026: "Zet
   *  meer een regel brede add-chip per sectie dan"). De kaart-ghost was één
   *  verzamelblok met alle drie de segmenten onder de héle regellijst; nu zet de
   *  leeskant er één per sectie neer, elk met de soort van díe sectie. Weglaten
   *  betekent alle drie — dat is nog steeds de vorm van het verzamelblok voor de
   *  soorten die op deze kaart nog geen enkele regel hebben. */
  soorten?: RegelSoort[];
  /** WAAR deze plek staat, en dus hoe breed hij is:
   *
   *   - `'sectie'` — als laatste kind van zijn eigen sectie, over de volle
   *     rijbreedte: het nieuwe element verschijnt direct BOVEN de chip, en dat
   *     is precies wat de eigenaar miste ("Bij die volgorde zie je de chips dus
   *     niet inline verschijnen");
   *   - `'verzamel'` — de compacte rij onderaan de regellijst, voor de soorten
   *     waarvan er nog geen enkele regel is. Zonder die rij zou een kaart zonder
   *     verboden nergens een verbod kunnen krijgen, en een lege sectiekop
   *     bouwen om er één chip in te hangen is precies wat review C-1 verbiedt.
   *
   *  Weglaten = `'verzamel'`: dat is de oude vorm en dus de veilige terugval. */
  plaatsing?: 'sectie' | 'verzamel';
}

/** Wat een REGEL-/PLICHTRIJ-plek nodig heeft. `ouder` is de knoop waaronder
 *  deze rij getekend staat (de kaart, of de regel waar de plicht onder hangt) —
 *  de VOORKEUR bij het zoeken van de koppeling die het ✕ en het ⧉ gebruiken.
 *  Zonder hem is een gedeelde plicht niet los te maken zonder te gokken welke
 *  van haar ouders bedoeld is; zie `knoopAnker` in de integratielaag. */
export interface RegelHaakCtx {
  regel: Regel;
  soort: RegelSoort;
  ouder?: unknown;
  /** Een GROEPEERNIVEAU of een andere weergave-constructie: geen eigen knoop in
   *  de graaf, dus alle iconen uit met de reden erbij. */
  afgeleid?: boolean;
  /** SEAM NAAR lane-velden: de stand van het ✎ op de rijkop (het inline
   *  naamveld). Zie `KaartHaakCtx.titelBewerk`. */
  titelBewerk?: unknown;
  /** De IRI van de KAART waarin deze rij staat (`RegelRijProps.scope`). Het
   *  gedeeld-merkteken licht bij het aanwijzen de ÁNDERE kaarten op waarin
   *  dezelfde knoop leeft; die ene mag hij overslaan, want daar kijk je al naar. */
  scope?: string | null;
  /** DE DIMENSIES WAAROP DE WEERGAVE NU GROEPEERT, in nestvolgorde
   *  (`actieveDimensies()`). De voorwaarde-ghost gebruikt ze voor de
   *  snelkoppeling van eigenaarsverfijning 1c: een regel die de buitenste
   *  dimensie mist, kan haar hier alsnog krijgen.
   *
   *  ZE KOMEN VIA DE CTX EN NIET VIA EEN IMPORT, en dat is een BYTE-argument.
   *  `ui/lijst/pivot.tsx` zit in de leeschunk; één import ernaartoe vanuit de
   *  bewerkchunk maakt hem tot GEDEELDE chunk, en dan laadt de leesinstap twee
   *  scripts waar er één stond (gemeten: 24,7 kB js + 17,8 kB css apart). De
   *  leeskant kent de keuze toch al — hij tekent de groepsrijen. */
  dims?: { iri: string; label?: string | null; curie?: string | null }[];
}

/** Wat de plek onderaan een GROEPEERNIVEAU nodig heeft (eigenaarsbesluit 8 sep
 *  2026, eis 5: in een dimensie-weergave hoort de ghost óók te verschijnen, en
 *  een toevoeging daar krijgt de dimensie-voorwaarde voorgevuld).
 *
 *  Een groepeerniveau heeft géén eigen knoop in de graaf — het is een indeling
 *  die `groupRules` uit refinement-waarden afleidt. De mutatie hangt dus aan de
 *  KAART (`pol`), en wat het niveau toevoegt is de VOORWAARDE die de nieuwe regel
 *  in dit vakje laat vallen: `dimIri` is de linkerkant (odrl:purpose voor een
 *  doelbinding), `waardeIri` de rechterkant. */
export interface GroepHaakCtx {
  pol: Policy;
  soort: RegelSoort;
  /** De dimensie van dit niveau: het leftOperand waarop `groupRules` indeelt. */
  dimIri: string;
  /** De waarde van dit niveau; zonder IRI valt er niets voor te vullen. */
  waardeIri?: string | null;
  waardeLabel?: string | null;
}

/** Wat een VOORWAARDERIJ-plek nodig heeft.
 *
 *  GEEN `slotBewerk`-SEAM MEER. Hier stond een derde veld: de stand van het ✎
 *  dat de sloteditor opent, "te vullen door lane-formulieren".
 *
 *  DE REDEN, PRECIES (bijgesteld door de fold, gemeten): die seam was NIET "per
 *  constructie onvulbaar" — dat is te sterk. `IcoonStand` is een kale datavorm
 *  (`aan`, `titel`, `actie?`, `opPointerDown?`) en het veld stond als `unknown`,
 *  dus `ui/kaart/voorwaarden.tsx` kon er een objectliteraal in zetten met een
 *  actie die de bewerklaag DYNAMISCH binnenhaalt. Nagedraaid met precies die
 *  probe: `lazy-grens.test.ts` bleef 5/5 groen. Er is dus geen structurele
 *  onmogelijkheid.
 *
 *  Wat er wél aan de hand was: de seam stond leeg en zou de leeskant dwingen de
 *  strook-logica na te bouwen om hem zinvol te vullen — de stand van een ✎
 *  (wanneer aan, met welke reden gedimd) hoort bij de strook, en die wordt in
 *  de bewerklaag gebouwd. Daarom ontstaat het ✎ nu waar het hoort en is de seam
 *  weg; niet omdat het niet kón, maar omdat het de verkeerde kant was. Het ✎
 *  ontstaat sinds de sloteditor-ronde in `ui/bewerk/integratie/rij-bewerk.tsx`,
 *  dat de strook toch al bouwt. */
export interface VoorwaardeHaakCtx {
  c: unknown;
  regel?: Regel | null;
  /** De IRI van de KAART waarin deze rij staat. Alleen het gedeeld-merk
   *  gebruikt hem, en wel om zichzelf eruit te laten: "in 2 kaarten" licht de
   *  ANDERE kaart op, niet die waar je al naar kijkt. Dezelfde prop en dezelfde
   *  betekenis als `scope` op `RegelHaakCtx`. */
  scope?: string | null;
}

/** Wat de toevoegplek onder de AFBAKENING van een collectie nodig heeft
 *  (eigenaarsbevinding 9 sep 2026: "een PartyCollection met refinements [is]
 *  ook niet aan te maken").
 *
 *  Eén veld, want er valt hier niets te kiezen: een afbakening is een
 *  `odrl:refinement` op de collectie zelf. GEEN regel en geen actie-knoop — dat
 *  is precies het verschil met `voorwaardeGhost`, die zijn refinement aan de
 *  ACTIE van een regel hangt omdat het model zijn dimensies daar leest. Een
 *  collectie heeft geen actie; haar refinements hangen er rechtstreeks onder
 *  (`collectionIntension` in parse.js leest `odrl:refinement` op de knoop). */
export interface CollectieHaakCtx {
  /** De collectieknoop: een IRI of een term uit de graaf. */
  term: unknown;
}

/** Wat de DOELOBJECT-plekken nodig hebben (fase C taak 5, de target-route).
 *
 *  `iri` is het doelobject waar dit ✕ bij hoort; de "+ gegevensset"-plek laat
 *  hem weg. Twee plekken en niet één, omdat ze op verschillende plaatsen in de
 *  rij staan: het ✕ ín de tag die het weghaalt, de combobox erachter — waar de
 *  nieuwe tag komt te staan. */
export interface TargetHaakCtx {
  regel: Regel;
  iri?: string | null;
}

/** De plekken die de leescomponenten openhouden. Elke sleutel is optioneel:
 *  zolang de bewerklaag niet geladen is, staat er niets. */
export interface BewerkHaken {
  /** De actiestrook op de kaartkop (⠿ uit, ✎ van lane-velden, ⧉, ✕). */
  kaartkop?: (ctx: KaartHaakCtx) => JSX.Element;
  /** De toevoegplek voor regels op een kaart: +toestemming, +verbod,
   *  +verplichting. Sinds 9 sep staat hij niet meer één keer onder de hele
   *  lijst, maar per SECTIE (zie `KaartHaakCtx.soorten`/`plaatsing`); de
   *  leescomponent roept hem dus meer dan eens aan. */
  kaartGhost?: (ctx: KaartHaakCtx) => JSX.Element;
  /** De ghost-KAART onder een aanbod: + overeenkomst op dit aanbod. */
  overeenkomstGhost?: (ctx: KaartHaakCtx) => JSX.Element;
  /** De actiestrook op een regel-/plichtrij. */
  regelStrook?: (ctx: RegelHaakCtx) => JSX.Element;
  /** De ghost-rij onderaan de plichtenlijst van een regel. */
  plichtGhost?: (ctx: RegelHaakCtx) => JSX.Element;
  /** De ghost-rij onderaan een GROEPEERNIVEAU: dezelfde toevoeging als op de
   *  kaart, maar met de voorwaarde van dít niveau al ingevuld. */
  groepGhost?: (ctx: GroepHaakCtx) => JSX.Element;
  /** Het ✕ in de tag van één doelobject. */
  targetKruis?: (ctx: TargetHaakCtx) => JSX.Element;
  /** "+ gegevensset" achter de doelobjecten van een regel. */
  targetGhost?: (ctx: TargetHaakCtx) => JSX.Element;
  /** De actiestrook op een voorwaarderij. */
  voorwaardeStrook?: (ctx: VoorwaardeHaakCtx) => JSX.Element;
  /** De ghost-rij onderaan de voorwaardenlijst van een regel. */
  voorwaardeGhost?: (ctx: RegelHaakCtx) => JSX.Element;
  /** De ghost-rij onderaan de AFBAKENING van een collectie: "+ afbakening". */
  collectieGhost?: (ctx: CollectieHaakCtx) => JSX.Element;
  /** "+ nieuw beleid": de ghost-KAART bovenaan de aanbodsectie, die een leeg
   *  drietraps in de bewerkbron zet (fase C taak 7). De enige plek zonder eigen
   *  knoop — vandaar een lege ctx. */
  nieuwBeleid?: (ctx: Record<string, never>) => JSX.Element;
}

/** DE ONTHULLER VAN DE GHOSTS (dt3-spec §1, de gelabelde dichtheidsverbetering).
 *
 *  Hij hoort op de KAART-/RIJWORTEL, en daarom woont de constante hier en niet
 *  in `ui/bewerk/ghost.tsx`: de wortel wordt door de LEEScomponenten getekend, en
 *  die mogen geen byte van de bewerklaag importeren. Het is een kale tekenreeks
 *  — geen import, geen CSS — dus de leeschunk betaalt er niets voor.
 *
 *  WAAROM DE WORTEL EN NIET DE GHOST (review I-1). De klasse zat op een `<div>`
 *  die de ghost onmiddellijk omhulde, en `.ghost-onthullen:hover .ghost-rij`
 *  werd daarmee "de ghost onthult zichzelf": wie over de kaart bewoog zag niets
 *  en moest de muis over een onzichtbare strook bewegen om te ontdekken dat daar
 *  iets stond. bewerk.css beschrijft de bedoelde vorm letterlijk ("tot de muis
 *  boven ZIJN KAART komt"), en de actiestrook hangt zijn dempte al aan de rij.
 *  CSS kan niet omhoog kijken — dus moet de wortel de klasse dragen.
 *
 *  `ui/bewerk/ghost.tsx` her-exporteert hem, zodat golf A's contract op zijn
 *  eigen plek leesbaar blijft. */
export const GHOST_ONTHUL_KLASSE = 'ghost-onthullen';

/** De onthul-klasse voor een kaart-/rijwortel, of `''` in de kijkstand: zonder
 *  ghosts valt er niets te onthullen, en een klasse die daar permanent op elke
 *  kaart staat nodigt de volgende stijlregel uit erop te mikken. */
export const ghostOnthulKlasse = (): string => (bewerklaagActief() ? ` ${GHOST_ONTHUL_KLASSE}` : '');

// --- HET FOCUSVERZOEK NA EEN TOEVOEGING --------------------------------------
//
// CONTRACTUITBREIDING (dt3, lane-toevoegfocus; eigenaarsbesluit 8 sep 2026: "je
// springt direct naar het nieuwe item in edit mode, titel editable at least").
//
// Het probleem is dezelfde omkering als hierboven. De ghost die de toevoeging
// doet zit in de BEWERKchunk; het titelveld van het nieuwe element wordt getekend
// door de LEEScomponent (`kaart.tsx`, `regels.tsx`) die de bewerklaag niet mag
// kennen. De twee kunnen elkaar dus niet aanroepen — vandaar één signaal met het
// ADRES van de knoop die de cursor hoort te krijgen. De ghost zet het adres zodra
// zijn mutatie klaar is; het veld dat zich op dat adres herkent, opent zich en
// wist het verzoek.
//
// EEN ADRES EN GEEN VERWIJZING, en dat is wezenlijk: het nieuwe element bestaat
// op het moment van het verzoek nog niet als component (de modelherbouw maakt hem
// pas), dus er is niets om een referentie naar vast te houden. Het adres
// overleeft de herbouw omdat het uit de graaf komt.
const [focusVerzoek, zetFocusVerzoek] = createSignal('');

/** HET ADRES VAN EEN KNOOP, in de ene vorm die aan beide kanten van de lazy-grens
 *  te maken is. `id` en niet `value`: een blanke knoop heet `_:b12` in zijn `id`
 *  en `b12` in zijn `value`, en de bewerkkant (een echte N3-term) en de leeskant
 *  (een structured-cloned worker-handle met alléén `id`) moeten dezelfde string
 *  opleveren. Voor een benoemde knoop zijn `id` en `value` allebei de IRI. */
export function focusAdres(x: unknown): string {
  if (!x) return '';
  if (typeof x === 'string') return x;
  const o = x as { id?: string; value?: string };
  return o.id || o.value || '';
}

/** Welk element vraagt op dit moment om de cursor? Leeg = geen verzoek. */
export const bewerkFocus = focusVerzoek;

/** Zet het verzoek (het adres van de zojuist ontstane knoop). */
export function vraagBewerkFocus(adres: string): void { zetFocusVerzoek(adres || ''); }

/** Het verzoek is ingelost (of vervalt). Wie hem inlost, wist hem: een verzoek
 *  dat blijft staan zou bij de volgende herbouw een tweede keer een veld
 *  openzetten dat de lezer net had gesloten. */
export function wisBewerkFocus(): void { zetFocusVerzoek(''); }

/** ÉÉN WISPOLICY VOOR ALLE TOEVOEGROUTES (opruimpunt 22, 10 sep 2026).
 *
 *  Er stonden er DRIE, elk met een eigen aangrijpingspunt: het tekstveld wiste
 *  bij het OPENEN, de IRI-combobox bij de AANNAME, en de voorwaarderij hield een
 *  eigen `nam()`-signaal aan om hetzelfde te doen als het tekstveld. Twee van de
 *  drie zeggen hetzelfde ding met andere woorden, en de derde — wissen bij de
 *  aanname — is aantoonbaar fout zodra de rij na een mutatie meer dan één keer
 *  wordt opgebouwd: de instantie die het verzoek aanneemt kan dezelfde zijn die
 *  meteen daarna wordt weggegooid, en de instantie die blijft staan vindt dan
 *  een leeg verzoek. Dat faalt STIL — de cursor landt nergens en geen enkele
 *  toets wordt er rood van.
 *
 *  De ene policy: HET VERZOEK IS PAS INGELOST ALS EEN VELD DAT ÉCHT IN HET
 *  DOCUMENT STAAT DE CURSOR HEEFT. Elke instantie op dat adres probeert zich te
 *  openen; alleen degene die het overleeft komt hier langs. En alleen als het
 *  verzoek nog over DÍT adres gaat: een late instantie mag het verzoek van een
 *  volgende toevoeging niet opruimen. */
export function wisFocusVoor(adres: string): void {
  if (adres && focusVerzoek() === adres) zetFocusVerzoek('');
}

const [haken, zetHaken] = createSignal<BewerkHaken>({});

export { haken };

/** Hangt de bewerklaag in (of, met `null`, weer uit). Idempotent genoeg om
 *  twee keer aangeroepen te worden; de laatste wint. */
export function koppelBewerkhaken(nieuw: BewerkHaken | null): void {
  zetHaken(nieuw || {});
}

/** Staat de bewerklaag ingehangen ÉN de bewerkstand aan? De leescomponenten
 *  gebruiken dit om een sectie te tonen die in de KIJKSTAND leeg zou blijven —
 *  de regellijst van een kaart zonder regels, de voorwaardensectie van een regel
 *  zonder voorwaarden. Zonder die uitzondering is er geen plek om de eerste toe
 *  te voegen (zelfde afweging als `constraintsSection` in de bevroren viewer).
 *
 *  DEZELFDE POORT ALS `Haak` HIERONDER, en om dezelfde reden (review C-1). Deze
 *  toets telde alleen of de haken gevuld waren. Dat viel tot de golf B-verzoening
 *  samen met "de bewerkstand staat aan"; sinds de chrome van lane-velden de
 *  enige lader is, niet meer. Gevolg was een LEESregressie op het gewone pad: wie
 *  de bewerkstand één keer aan- en weer uitzette hield de rest van zijn sessie
 *  lege "Voorwaarden"/"Verplichtingen"/"Regels"-koppen — 44 gemeten op het
 *  demo-corpus. `Haak` rendert er terecht niets in; de KOP bleef staan.
 *
 *  De twee poorten horen daarom dezelfde te zijn. Ze staan bewust náást elkaar en
 *  niet in één helper: `Haak` poort per plek in de JSX, deze per sectie in de
 *  leescomponent, en de gedeelde helper zou de tweede lezing verbergen. */
export const bewerklaagActief = (): boolean =>
  weergave.editMode && Object.keys(haken()).length > 0;

/** Eén plek. `naam` kiest de haak, `ctx` is wat zij nodig heeft.
 *
 *  De haak wordt BINNEN de JSX uitgelezen, dus de plek vult (en leegt) zichzelf
 *  zodra de laag komt of gaat — de kaart eromheen hoeft niet opnieuw te
 *  renderen. Dat is precies wat de scroll-stabiliteit nodig heeft: het
 *  verschijnen van de bewerkaffordances is een lokale verandering. */
export function Haak<K extends keyof BewerkHaken>(props: {
  naam: K;
  ctx: Parameters<NonNullable<BewerkHaken[K]>>[0];
}): JSX.Element {
  return (
    <>
      {(() => {
        // DE BEWERKSTAND MOET AAN STAAN, niet alleen de laag geladen zijn.
        //
        // Dit was tot de verzoening van golf B één en hetzelfde: de lader van
        // deze module haalde de laag pas op bij `editMode && bewerkbron`, dus
        // "haken gevuld" impliceerde "bewerkstand aan". Sinds de bewerkchrome
        // van lane-velden de enige lader is, geldt dat niet meer — en dan moet
        // het hier alsnog worden gezegd.
        //
        // Het geval dat het aantoonde: `?edit=1` op een corpus ZONDER
        // bewerkbron. De chrome laadt de laag (terecht — het AANBOD om een
        // bewerkbron te kiezen zit erin), `bevestigEditMode` zet de stand
        // daarna correct weer uit en haalt `?edit=` uit de adresbalk, maar de
        // haken bleven gevuld: gemeten 60 actiestroken en 180 knoppen op een
        // pagina die in de KIJKstand staat. Dat is precies de fout die de
        // lazy-grens niet vangt, want er is geen byte te veel geladen — hij
        // wordt alleen getoond op het verkeerde moment.
        if (!weergave.editMode) return null;
        const fn = haken()[props.naam] as ((c: unknown) => JSX.Element) | undefined;
        return fn ? fn(props.ctx) : null;
      })()}
    </>
  );
}

// --- GEEN LADER MEER IN DEZE MODULE ------------------------------------------
//
// Deze module bood zijn eigen lader aan zolang er nog geen bewerkchrome was, en
// voorzag in de kop van dit bestand al dat lane-velden hem zou overnemen. Dat
// moment kwam met de verzoening van 7 sep 2026: `ui/app/bewerkstand.tsx` laadt
// de laag via de bevestigflow, en `startLader()` verdween van moduleniveau.
//
// WAT ER TOEN BLEEF STAAN, MET EEN ONWARE MOTIVERING (eindreview I-4):
// `laadBewerklaag()`, `startLader()` en `stopLader()` bleven als export achter,
// met de toelichting dat "de tests van deze module ze gebruiken" en dat
// `laadBewerklaag()` het pad was dat `laag.tsx` gebruikt. Geen van beide was
// waar: nul aanroepers in `src/`, `test/`, `tools/` en `viewer-bevroren/test/`, en
// `laag.tsx` importeert `integratie/mount.js` STATISCH. Ze zijn nu weg.
//
// DRIE DINGEN DIE DAARMEE KLOPPEN in plaats van bijna-kloppen:
//
// 1. ÉÉN LAADWORTEL. Een tweede `import('../bewerk/integratie/mount.js')` in de
//    LEESCHUNK is een tweede dynamische wortel en dus een tweede chunkboom —
//    exact de preload-keten waar de golf-B-verzoening om draaide. Dat hij nu
//    dood was maakte hem goedkoop, niet onschuldig: hij stond er als een
//    uitnodiging om hem weer aan te zetten.
// 2. ÉÉN `laadBewerklaag`. De naam bestond twee keer, in twee chunks en met een
//    eigen idempotentie-toestand (`ui/app/bewerkstand.tsx` r.60 en hier) —
