// DE ACTIES BIJ ÉÉN BRON: ✎ bewerkbaar maken, ↶ terugdraaien, ⤓ downloaden,
// ✕ verwijderen. Plus de endpointregel, die dezelfde acties in zijn eigen vorm
// draagt.
//
// HERONTWERP 9 SEP 2026, eigenaar, letterlijk: "Eerst alleen een lijst van
// bronnen met een edit en x/delete icoontje ernaast en bron toevoegen met URL
// veld. Als je het edit icoontje klikt naast die bron wordt het direct editable
// en krijg je een revert icoontje en download icoontje. Revert zet alles terug
// en maakt het weer onbewerkbaar. Download is download. Delete is delete."
//
// WAT DAARMEE VERVALT: het SLOTJE als keuzerondje. Tot vandaag was de lijst een
// `radiogroup` waarin één bron het rondje droeg (spec-addendum 6 sep: er is
// altijd precies één bewerkbare bron). Dat MODEL blijft ongewijzigd gelden — de
// bronnenlaag kent nog steeds één bewerkbron, `maakBewerkbaar` zet de vorige
// vanzelf terug op lezen — maar het is geen zichtbaar keuze-element meer. Wat
// de lezer ziet is per rij een STAND: hij kan bewerkbaar gemaakt worden (✎), of
// hij is het (↶ ⤓). De keuze-uit-veel staat nu in de modal achter de
// bewerkknop, waar hij hoort: daar wordt hij gesteld.
//
// DE RIJ HEEFT DUS TWEE VORMEN, en de wissel ertussen IS de terugkoppeling van
// de klik. Geen dialoog, geen bevestiging (eigenaarsbesluit 9 sep: "make
// editable doesn't need a confirmation button"): één klik op ✎ schrijft de
// lokale kopie en het icoonrijtje verspringt.
//
// DEZE MODULE IS EAGER, en dat is een wijziging. Hij heette `bronnen-bewerk.tsx`
// en hing achter een `lazy()` omdat mutatie-affordances bij de bewerkstand
// hoorden. In het herontwerp horen ze bij ELKE stand — een corpus samenstellen
// en een bron bewerkbaar maken is bronbeheer, geen documentbewerking — dus is er
// niets meer om lazy te maken. De harde eis van spec §1 blijft: de BEWERKLAAG
// (`ui/bewerk/**`, `stores/bewerk.ts`, `model/edit.js`) komt pas over de lijn bij
// de eerste klik op de bewerkknop, en dat bewaakt `stores/lazy-grens.test.ts` op
// het pad `ui/bewerk/`. Alles wat hier gebruikt wordt komt uit
// `stores/bronbeheer.ts`, die de schil toch al eager laadt (`startBronbeheer` in
// src/app.tsx); de serialisatie erachter (`model/edit.js`) haalt `downloadBron`
// zelf dynamisch op.
import { createEffect, createSignal, onCleanup, Show } from 'solid-js';
import { endpoint } from '../../stores/corpus.js';
import {
  bewerkbron, downloadBron, herstelOrigineel, maakBewerkbaar, maakEndpointBewerkbaar,
  opfsAan, updateUrlVoorstel, vergrendelEndpoint, verwijderBron,
} from '../../stores/bronbeheer.js';
import type { BronBewerk } from '../../stores/bronbeheer.js';
import { tekst } from '../../stores/weergave.js';
import { Srcknop } from './bronnen.jsx';

/** ÉÉN DOWNLOADKNOP MET EEN MENU.
 *
 *  EIGENAARSBESLUIT 9 SEP 2026, letterlijk: "De downloads mag ook gewoon één
 *  download icoon zijn met dropdown die je ttl of json laat kiezen". Hij staat
 *  alleen bij de bron die bewerkbaar IS — in het herontwerp volgt dat vanzelf
 *  uit de icoonwissel, en het klopt nog steeds met de verfijning van diezelfde
 *  dag ("Ik zou ook alleen bewerkte bestanden laten downloaden ... dan is het
 *  duidelijker waarom dat zo is"): een onbewerkte bron is het origineel, dat heb
 *  je al, en de naam ernaast linkt ernaartoe.
 *
 *  MENU-PATROON: `aria-haspopup="menu"` + `aria-expanded` op de knop,
 *  `role="menu"` op de lijst, `role="menuitem"` op de keuzes;
 *  Enter/Spatie/Pijl-omlaag opent en zet de focus op de eerste keuze, pijltjes
 *  lopen rond, Escape sluit en geeft de focus terug. Escape STOPT hier: hij mag
 *  niet doorlopen naar de escape-lagen van de pagina (bronnenpaneel → zijnav),
 *  want wie een menu open heeft, sluit met Escape dat menu. */
export function Downloadmenu(props: { bron: BronBewerk }) {
  const [open, zetOpen] = createSignal(false);
  let knopEl: HTMLButtonElement | undefined;
  let wikkelEl: HTMLSpanElement | undefined;

  const items = (): HTMLButtonElement[] =>
    [...(wikkelEl?.querySelectorAll<HTMLButtonElement>('[role="menuitem"]') ?? [])];

  /** Sluiten en de focus terug naar de knop — het menu is weg, de focus mag
   *  niet met hem meeverdwijnen naar <body>. */
  const sluit = (terug = true) => {
    zetOpen(false);
    if (terug) knopEl?.focus();
  };
  const openMet = (welke: 'eerste' | 'laatste') => {
    zetOpen(true);
    const l = items();
    (welke === 'eerste' ? l[0] : l[l.length - 1])?.focus();
  };
  const kies = (formaat: 'ttl' | 'jsonld') => {
    void downloadBron(props.bron, formaat);
    sluit();
  };

  // KLIKKEN BUITEN HET MENU SLUIT HET. Zonder dit blijft een opengelaten menu
  // over de rij eronder liggen; een muisgebruiker die ergens anders klikt
  // verwacht dat het weg is. Alleen zolang het open staat, en met de wikkel als
  // grens — een klik op de knop zelf wordt door de knop afgehandeld.
  createEffect(() => {
    if (!open() || typeof document === 'undefined') return;
    const buiten = (e: Event) => {
      if (!wikkelEl?.contains(e.target as Node)) zetOpen(false);
    };
    document.addEventListener('pointerdown', buiten, true);
    onCleanup(() => document.removeEventListener('pointerdown', buiten, true));
  });

  return (
    <span
      class="src-downloadmenu"
      ref={wikkelEl}
      // `on:keydown` EN NIET `onKeyDown` — de escape-les van fase C, voluit
      // opgeschreven in ui/bewerk/veld.tsx. Solid DELEGEERT `onKeyDown` naar het
      // document, en een gedelegeerde handler draait pas als de gebeurtenis het
      // document al bereikt heeft: zijn `stopPropagation` komt dan te laat voor
      // de document-brede Escape-listeners (bronnenpaneel, invulling-paneel,
      // sectiefilter, zijnav). Een echte listener op dit element stopt hem in de
      // targetfase, dus vóór al die lagen.
      on:keydown={(e: KeyboardEvent) => {
        if (e.key === 'Escape' && open()) {
          e.preventDefault(); e.stopPropagation(); sluit(); return;
        }
        const l = items();
        const hier = l.indexOf(document.activeElement as HTMLButtonElement);
        if (e.key === 'ArrowDown') {
          e.preventDefault(); e.stopPropagation();
          if (!open()) { openMet('eerste'); return; }
          l[(hier + 1) % l.length]?.focus();
        } else if (e.key === 'ArrowUp') {
          e.preventDefault(); e.stopPropagation();
          if (!open()) { openMet('laatste'); return; }
          l[(hier - 1 + l.length) % l.length]?.focus();
        }
      }}
    >
      <button
        type="button"
        class="src-download"
        ref={knopEl}
        title={tekst('src.downloadMenu')}
        aria-label={tekst('src.downloadMenu')}
        aria-haspopup="menu"
        aria-expanded={open() ? 'true' : 'false'}
        onClick={() => (open() ? sluit() : openMet('eerste'))}
      >⤓</button>
      <Show when={open()}>
        <ul class="src-download-menu" role="menu" aria-label={tekst('src.downloadMenu')}>
          <li role="none">
            <button
              type="button"
              role="menuitem"
              class="src-download-ttl"
              title={tekst('src.download')}
              onClick={() => kies('ttl')}
            >{tekst('src.downloadTtlKort')}</button>
          </li>
          <li role="none">
            <button
              type="button"
              role="menuitem"
              class="src-download-jsonld"
              title={tekst('src.downloadJsonLd')}
              onClick={() => kies('jsonld')}
            >{tekst('src.downloadJsonLdKort')}</button>
          </li>
        </ul>
      </Show>
    </span>
  );
}

/** WAAROM DEZE BRON NIET BEWERKBAAR TE MAKEN IS, als i18n-SLEUTEL — of null als
 *  het wel kan. Twee gronden, allebei hard: zonder lokale opslag kan er geen
 *  kopie bestaan, en van een bron die niet gelezen kon worden zou de kopie LEEG
 *  zijn — die wist de bron dan in plaats van hem bewerkbaar te maken.
 *
 *  DE SLEUTEL EN DE TEKST ZIJN UIT ELKAAR GEHAALD (kruisbevinding
 *  lane/release-basis, browsermatrix dt4). Deze functie leverde alleen TEKST,
 *  want zij diende alleen tooltips. De potloodknop in de KOP heeft dezelfde
 *  reden nodig om hem te MELDEN, en `zetMelding` neemt een sleutel — een tekst
 *  erin duwen zou de melding onvertaalbaar maken en de taalwissel erop laten
 *  stilstaan. Vandaar twee functies: de sleutel is het gegeven, de tekst is de
 *  weergave ervan. */
export function weigergrondSleutel(bron: BronBewerk, fout?: string): string | null {
  if (bron.modus === 'readwrite' || bron.opfs) return null;
  if (!opfsAan()) return 'src.opfsUit';
  if (fout) return 'src.lockFout';
  return null;
}

/** Dezelfde grond, als leesbare zin — voor de tooltip van het ✎. */
export function weigergrond(bron: BronBewerk, fout?: string): string | null {
  const sleutel = weigergrondSleutel(bron, fout);
  return sleutel ? tekst(sleutel) : null;
}

/** Het ✎-icoontje: deze bron in ÉÉN klik de bewerkbron maken.
 *
 *  `aria-disabled` EN NIET `disabled`: `disabled` haalt de knop uit de
 *  focusvolgorde, en dan is de reden die hier zorgvuldig in de tooltip staat
 *  voor een toetsenbordgebruiker onbereikbaar. De weigering zelf gebeurt in de
 *  klik-afhandeling.
 *
 *  DE TOOLTIP ZEGT WAT DE KLIK GAAT DOEN, vóór de klik. Bij een bron zonder
 *  lokale kopie wordt er één geschreven, en dan hoort de opmaakverlies-zin
 *  erbij — die stond tot 9 sep 2026 in een bevestigdoosje eronder. */
function Bewerkbaarknop(props: { bron: BronBewerk; fout?: string }) {
  const reden = () => weigergrond(props.bron, props.fout);
  const titel = () => {
    const r = reden();
    if (r) return r;
    return props.bron.opfs
      ? tekst('src.kiesBewerkbron')
      : `${tekst('src.kiesBewerkbron')} — ${tekst('src.lockWaarschuwing')}`;
  };
  return (
    <button
      type="button"
      class="src-edit"
      title={titel()}
      aria-label={titel()}
      aria-disabled={reden() ? 'true' : undefined}
      onClick={() => {
        if (reden()) return;
        void maakBewerkbaar(props.bron);
      }}
    >✎</button>
  );
}

/** Het icoonrijtje van één bron. Twee vormen, en de wissel ertussen is de
 *  terugkoppeling van de klik:
 *
 *    ONBEWERKBAAR:  ✎ ✕
 *    BEWERKBAAR:    ↶ ⤓ ✕
 *
 *  ↶ ALLEEN BIJ EEN BRON MET EEN ORIGINEEL. "Terug naar origineel" haalt het
 *  originele bestand opnieuw op; een werkbestand heeft er geen, en de knop zou
 *  daar de enige kopie weggooien zonder iets terug te zetten. ⤓ staat er dan
 *  wél — juist daar, want dat bestand bestaat alleen in deze browser. */
export function Bronacties(props: { bron: BronBewerk; fout?: string }) {
  const bewerkbaar = () => props.bron.modus === 'readwrite';
  return (
    <span class="src-acties">
      <Show when={bewerkbaar()} fallback={<Bewerkbaarknop bron={props.bron} fout={props.fout} />}>
        <Show when={props.bron.url}>
          <Srcknop
            klasse="src-revert"
            label="↶"
            titel={tekst('src.unlock')}
            bij={() => void herstelOrigineel(props.bron)}
          />
        </Show>
        <Downloadmenu bron={props.bron} />
      </Show>
      {/* ✕ SLUIT DE RIJ AF, in beide vormen. Hij is de enige onomkeerbare
          handeling erin en hoort dus niet als eerste onder de muis te liggen.
          `verwijderBron` ruimt de lokale kopie mee op (ruimOpfsOp): een bron die
          weg is, hoort niet als spook in de OPFS-index achter te blijven en bij
          de volgende lading terug te komen. */}
      <Srcknop
        klasse="src-remove"
        label="✕"
        titel={tekst('src.remove')}
        bij={() => void verwijderBron(props.bron)}
      />
    </span>
  );
}

/** Het uitklapveldje voor de update-URL, in de endpointregel zelf. Die URL is
 *  een ANDERE service dan de query-URL en valt niet betrouwbaar af te leiden;
 *  vandaar een invoerveld met de gebruikelijke afleiding als voorstel. */
function UpdateUrlVeld(props: { ep: string; klaar: () => void }) {
  const [waarde, zetWaarde] = createSignal(updateUrlVoorstel(props.ep));
  return (
    <span class="src-update-veld">
      {' '}
      <input
        type="text"
        class="src-update-url"
        value={waarde()}
        aria-label={tekst('src.updateUrl')}
        title={tekst('src.updateUrl')}
        onInput={(e) => zetWaarde(e.currentTarget.value)}
      />
      {' '}
      <button
        type="button"
        class="src-update-ok"
        onClick={() => {
          const url = waarde().trim();
          if (!url) return;
          void maakEndpointBewerkbaar(url);
          props.klaar();
        }}
      >{tekst('src.updateOk')}</button>
    </span>
  );
}

/** DE ENDPOINTREGEL. Hij is geen bestand en heeft daarom zijn eigen vorm van
 *  dezelfde twee acties: ✎ vraagt eerst om de update-URL (er is niets af te
 *  leiden), ↶ laat het endpoint weer met rust. Geen ✕ — het endpoint komt uit de
 *  adresbalk, niet uit deze lijst — en geen ⤓: een endpoint downloaden is een
 *  query, geen bestand.
 *
 *  GEEN KNOP DIE NIETS DOET: het verzenden van een SPARQL Update hangt aan de
 *  mutatiekern (voerUit/bron-sync). Het ✎ kiest hier wél de update-URL en zet
 *  het endpoint als bewerkbron — dat is de KEUZE, die de mutatiekern uitleest. */
export function Endpointregel() {
  const [urlVeldOpen, zetUrlVeldOpen] = createSignal(false);
  const epAan = () => {
    const b = bewerkbron();
    return !!b && b.soort === 'sparql';
  };
  return (
    <Show when={endpoint()}>{(ep) => (
      <li class="muted src-endpoint-li" data-modus={epAan() ? 'readwrite' : 'read'}>
        <span class="src-naam">{ep()}</span>
        <span class="src-endpoint-note">{tekst('src.endpointNote')}</span>
        <Show when={epAan()}>
          <span class="src-lokaal">
            {' ' + tekst('src.updateNaar', { url: bewerkbron()?.updateUrl ?? '' })}
          </span>
        </Show>
        {' '}
        <span class="src-acties">
          <Show
            when={epAan()}
            fallback={
              <button
                type="button"
                class="src-edit"
                title={tekst('src.kiesBewerkbron')}
                aria-label={tekst('src.kiesBewerkbron')}
                onClick={() => zetUrlVeldOpen(true)}
              >✎</button>
            }
          >
            <Srcknop
              klasse="src-revert"
              label="↶"
              titel={tekst('src.stopBewerkbron')}
              bij={() => { void vergrendelEndpoint(); zetUrlVeldOpen(false); }}
            />
          </Show>
        </span>
        <Show when={urlVeldOpen() && !epAan()}>
          <UpdateUrlVeld ep={ep()} klaar={() => zetUrlVeldOpen(false)} />
        </Show>
      </li>
    )}</Show>
  );
}
