// HET ⌕ — de uitgang van elke knoop in het document naar de verkenner-stand.
//
// Bevinding C-1 van de einddoorloop: de bevroren viewer zet dit anker op de
// kaartkop, op elke kv-waarde, op elke regelkop, op de verwijzingsregels en op
// de ledenrijen (166/94/72/858 stuks op de vier meetcorpora); in de nieuwe app
// stond er nul. De verkenner was daarmee vanuit het document onbereikbaar —
// alleen nog via een `?verken=`-deeplink of via het invulling-paneel.
//
// Gedragsbron: `verkenBtn` (viewer-bevroren/assets/doc.js r.892) plus `verkenLink`
// (viewer-bevroren/assets/verken.js r.178). Woord voor woord hetzelfde:
//
//   * een echte `<a href="?verken=<IRI>">` — deelbaar, en middelklik,
//     "openen in nieuw tabblad" en kopiëren blijven van de browser;
//   * een gewone linkerklik wisselt de pagina van STAND zonder te herladen
//     (openVerken): de store blijft staan, dus heen en weer is instant;
//   * `stopPropagation`, want de rij eronder mag niet meespringen — een ⌕ op
//     een `<summary>` zou anders de kaart openklappen.
//
// GEEN ⌕ ZONDER ADRES. Een blanke knoop (een naamloze regel, een anonieme
// policy, een blanke voorwaarde) heeft buiten dit document geen IRI en is dus
// niet aan te wijzen — niet in een deelbare URL en niet in een externe
// verkenner. `iriOf` levert daar `null` en de knop valt weg in plaats van dood
// te staan. Daarom mag elke aanroeper hem blind neerzetten: hij regelt zijn
// eigen afwezigheid.
import { Show } from 'solid-js';
import type { JSX } from 'solid-js';
import { tekst } from '../../stores/weergave.js';
import { iriOf } from './verken-url.js';
import type { TermOfIri } from './verken-url.js';
import { openVerken, verkenUrl } from './verken-history.js';
// De vorm van `.verken-btn` (maat, rand, hover, dark-mode) staat in verken.css;
// dit bestand draagt hem het hele document door en hoort hem dus mee te nemen.
import './verken.css';

export function VerkenKnop(props: {
  /** De knoop: een IRI, een N3-term of een kale `{ id }`-handle uit de worker.
   *  Niet `ref`: dat is in Solid de gereserveerde naam voor een element-handle.
   *
   *  BEWUST `unknown`. De modellaag is nog JavaScript en levert dit veld op
   *  tientallen plekken in drie vormen; elke aanroeper zou anders een cast
   *  moeten schrijven om `pol.term` (van type `unknown`) door te geven. `iriOf`
   *  is totaal en geeft op alles wat geen bruikbare IRI is netjes `null`, dus
   *  een verkeerde waarde levert hier geen fout maar geen knop. */
  doel: unknown;
  /** De hover van dit specifieke ⌕ ("Verken het aangevraagde aanbod"). Zonder
   *  titel de generieke tekst, zoals `verkenBtn(iri)` zonder tweede argument. */
  titel?: string | null;
}): JSX.Element {
  const iri = () => iriOf(props.doel as TermOfIri);
  const hint = () => props.titel || tekst('verken.title');
  return (
    <Show when={iri()}>{(v) => (
      <a
        class="verken-btn"
        href={verkenUrl(v())}
        title={hint()}
        aria-label={tekst('verken.aria')}
        onClick={(e) => {
          e.stopPropagation();
          // Modifier- en middelklik blijven van de browser (nieuw tabblad/
          // venster): zelfde regel als bij de kruisverwijzingen in het document.
          if (e.metaKey || e.ctrlKey || e.shiftKey || e.altKey || e.button) return;
          e.preventDefault();
          openVerken(v());
        }}
      >{'⌕'}</a>
    )}</Show>
  );
}
