// HET INVULLING-PANEEL: de keten rond één element, naast het document.
//
// Herbouw van het invulling-paneelblok van de bevroren viewer
// (viewer-bevroren/assets/doc.js: buildFillIndex, fillFulfilledBy/fillFulfils, fillRow,
// renderFill, openFill, plus het overlay-/vouw-/Escape-blok eromheen). Het ⚙ op
// een regel, een voorwaarde of een conformsToPolicy-rij opent hier het
// rechterpaneel op DAT element; het paneel toont de keten:
//
//     ↑ Wordt ingevuld door     (wat dit element uitwerkt)
//     ── het element zelf ──    (grijs vlak, met de herkomst eronder)
//     ↓ Geeft invulling aan     (wat dit element zelf invult)
//
// ZIJPANEEL, GEEN OVERLAY (besluit eigenaar, aug 2026): het paneel dekt het
// document niet af maar duwt het opzij (`body.panel-open`), zodat de lezer de
// invulling én de regel waar zij bij hoort tegelijk ziet. Geen backdrop, geen
// scroll-lock, geen focus-trap: een klik in het document sluit het paneel niet,
// alleen ✕ en Escape doen dat.
//
// HET PANEEL ADRESSEERT DE WEERGAVE VIA `data-ref` — het contract dat de
// kaartlaag zet (taak 4): elke rij in het paneel is een DUPLICAAT van een rij in
// het document, hoveren markeert de bron, "→" springt erheen en het eigen ⚙ zet
// het paneel op dát element.
import { createEffect, createMemo, createSignal, For, Match, onCleanup, Show, Switch } from 'solid-js';
import type { JSX } from 'solid-js';
import { coverageNext, curie } from '../../model/parse.js';
import { model } from '../../stores/corpus.js';
import { tekst, weergave } from '../../stores/weergave.js';
import { RegelBadge } from '../gedeeld/chip.jsx';
import type { RegelSoort } from '../gedeeld/chip.jsx';
import { VerkenKnop } from '../verken/verken-knop.jsx';
// DE VOORWAARDE-WIDGETS KOMEN UIT DE KAARTLAAG, niet uit een eigen kopie hier
// (die kopie is precies wat de eindreview als IMP-2 vond). Ze komen uit
// `voorwaarde-inhoud.tsx` en NIET uit `voorwaarden.tsx`: dat laatste bestand
// haalt `InvullingKnop` hiervandaan, en die lus is bij de dt3-opruiming
// doorgeknipt. De inhoudslaag kent het paneel niet, dus de draad loopt nu één
// kant op.
import { ChipRuimte, VoorwaardeInhoud } from './voorwaarde-inhoud.jsx';
import type { Voorwaarde as KaartVoorwaarde } from './voorwaarde-inhoud.jsx';
import './invulling.css';

// ============================================================================
// Wat het paneel van het model leest
// ============================================================================
// De modellaag is nog JavaScript; deze typen beschrijven de dekkingskant van
// `buildModel` in de mate waarin het paneel haar gebruikt. Ze horen bij de
// modeltypen in kaart.tsx en verhuizen met dat blok mee zodra de modellaag zelf
// getypeerd is (ruling 2 van taak 4).

/** Een voorwaarde (odrl:Constraint), inclusief de conformsToPolicy-ankerrij:
 *  die is een blanke knoop en draagt daarom een samengestelde `rowRef`.
 *
 *  DE VORM KOMT UIT `voorwaarde-inhoud.tsx` en wordt hier alleen UITGEBREID met de
 *  drie ketenvelden die het paneel leest. Tot de fixgolf van de eindreview
 *  stond hier een tweede, met de hand geschreven beschrijving van dezelfde
 *  modelvorm — en die was al uit de pas gelopen (`logical` stond er als
 *  `boolean`, terwijl parse.js r.853 de operatornaam als string zet). Twee
 *  beschrijvingen van één modelvorm is dezelfde fout als twee kopieën van één
 *  widget; dit type is nu de enige. */
export interface Voorwaarde extends KaartVoorwaarde {
  /** De N3-term van de knoop: wat het ⌕ nodig heeft als er geen IRI is. */
  term?: unknown;
  realises?: string[] | null;
  fulfils?: { iri: string }[];
}

/** De dekking van één regel zoals parse.js/ruleCoverage hem oplevert. */
export interface Dekking {
  status?: string;
  rule: { iri: string }[];
  conditions: Map<string, unknown>;
  uncovered?: string[];
  uncoveredReasons?: Record<string, string>;
  inConformsContext?: boolean;
  organisational?: boolean;
  via?: ViaSchakel[];
}

/** Een keten-schakel: een voorwaarde die een plicht uitwerkt, en de artefacten
 *  die díe voorwaarde afdwingen. */
export interface ViaSchakel {
  constraint?: Voorwaarde;
  artefacts: { iri: string }[];
  policies?: string[];
}

/** Een regel met haar dekking (toestemming, verbod of verplichting). */
export interface DekkingsRegel {
  iri?: string | null;
  title?: string | null;
  label?: string | null;
  action?: { label?: string } | string | null;
  kind?: string;
  purposeConstraint?: Voorwaarde | null;
  constraints?: Voorwaarde[];
  refinements?: Voorwaarde[];
  duties?: DekkingsRegel[];
  coverage?: Dekking | null;
  coveredBy?: { iri: string }[];
}

/** Een beleidsstuk, zoals de index het afloopt. */
export interface DekkingsPolicy {
  iri: string;
  anon?: boolean;
  title?: string | null;
  permissions?: DekkingsRegel[];
  prohibitions?: DekkingsRegel[];
  obligations?: DekkingsRegel[];
  inherited?: { title?: string; curie?: string; iri?: string; rules?: { type: string; rule: DekkingsRegel }[] }[];
}

/** Het model in de mate waarin dit bestand het leest. */
export interface DekkingsModel {
  sets: DekkingsPolicy[];
  offers: DekkingsPolicy[];
  agreements: DekkingsPolicy[];
  artifacts?: { iri: string; title?: string | null }[];
  bundles?: { iri: string; title?: string | null }[];
}

/** Eén ingang van de opzoektabel: wat er achter een `data-ref` zit. `scopes` is
 *  de HERKOMST — een gedeelde stelselplicht staat in meer beleidssets, en dat
 *  mag de kop van het paneel gewoon zeggen. */
export interface Ingang {
  type: 'rule' | 'condition' | 'conforms';
  ref: string;
  kind: RegelSoort;
  rule?: DekkingsRegel;
  constraint?: Voorwaarde;
  nodeIri?: string | null;
  plichten?: SetPlicht[];
  scopes: { iri: string | null; title: string }[];
}

/** Een blok rijen in een richting: een (optionele) subkop, de refs en de
 *  herkomst-notities per ref. */
export interface Blok { title: string | null; refs: string[]; notes?: Record<string, string> }

/** Een verplichting die voor élke regel van een beleidsset geldt, met de
 *  ouderset waaruit zij is overgenomen (null = van de set zelf). */
interface SetPlicht { duty: DekkingsRegel; from: string | null }

// ============================================================================
// De opzoektabel
// ============================================================================
// Het paneel werkt met REFS, niet met objecten: dezelfde `data-ref` waarmee een
// element in de weergave te vinden is (een IRI, of de samengestelde ref van een
// conformsToPolicy-rij — die is een blanke knoop). Deze index maakt van zo'n ref
// het element terug, en hij wordt uit het MODEL gebouwd: de dekking (coverage,
// rowRef, fulfils, realises) staat daar al uitgerekend. De graaf zou hem
// opnieuw moeten afleiden.

/** Alle voorwaarden die bij de regel zelf horen, IN DE VOLGORDE VAN DE KAART:
 *  doelbinding eerst, dan de eigen voorwaarden, dan de refinements. Het paneel
 *  toont dezelfde rijen in dezelfde volgorde als de kaart ernaast. */
export function eigenVoorwaarden(rule: DekkingsRegel): Voorwaarde[] {
  return [
    ...(rule.purposeConstraint ? [rule.purposeConstraint] : []),
    ...(rule.constraints || []), ...(rule.refinements || []),
  ];
}

/** De verplichtingen die voor élke regel van deze beleidsset gelden: haar eigen
 *  odrl:obligation plus de via odrl:inheritFrom overgenomen plichten, met de
 *  ouderset erbij (policyLevelDuties in de viewer). */
export function setPlichten(pol: DekkingsPolicy | null | undefined): SetPlicht[] {
  if (!pol) return [];
  const uit: SetPlicht[] = (pol.obligations || []).map((duty) => ({ duty, from: null }));
  for (const g of pol.inherited || []) {
    for (const e of g.rules || []) {
      if (e.type !== 'obligation') continue;
      uit.push({ duty: e.rule, from: g.title || g.curie || g.iri || null });
    }
  }
  return uit;
}

function regelSoort(rule: DekkingsRegel, verbod: boolean): RegelSoort {
  if (verbod) return 'verbod';
  return rule && rule.kind === 'duty' ? 'duty' : 'toestemming';
}

const allePolicies = (m: DekkingsModel | null): DekkingsPolicy[] =>
  (m ? [...m.offers, ...m.agreements, ...m.sets] : []);

/** Ref -> element. Per model één keer gebouwd (zie invullingIndex). */
export function bouwInvullingIndex(m: DekkingsModel | null): Map<string, Ingang> {
  const ix = new Map<string, Ingang>();
  if (!m) return ix;
  const voegToe = (ref: string | null | undefined, desc: Ingang) => {
    if (!ref) return;
    const cur = ix.get(ref);
    if (!cur) { ix.set(ref, desc); return; }
    // Dezelfde knoop in een tweede beleidsset: geen tweede ingang, wél een
    // tweede herkomst.
    for (const sc of desc.scopes) {
      if (!cur.scopes.some((x) => x.iri === sc.iri)) cur.scopes.push(sc);
    }
  };
  for (const pol of allePolicies(m)) {
    const scope = { iri: pol.anon ? null : pol.iri, title: pol.title || curie(pol.iri) };
    const plichten = setPlichten(pol);
    const loop = (rule: DekkingsRegel | null | undefined, kind: RegelSoort, diepte = 0): void => {
      if (!rule) return;
      voegToe(rule.iri, { type: 'rule', ref: rule.iri!, rule, kind, scopes: [scope] });
      for (const c of eigenVoorwaarden(rule)) {
        if (!c) continue;
        if (c.technicalMeasure && c.rowRef) {
          voegToe(c.rowRef, {
            type: 'conforms', ref: c.rowRef, constraint: c, rule, kind,
            nodeIri: c.conformsTo, plichten, scopes: [scope],
          });
        } else if (c.iri) {
          voegToe(c.iri, { type: 'condition', ref: c.iri, constraint: c, rule, kind, scopes: [scope] });
        }
      }
      // Plichten binnen een regel tellen mee, tot drie niveaus diep — zoals de
      // weergave ze ook nest.
      if (diepte < 3) for (const n of rule.duties || []) loop(n, 'duty', diepte + 1);
    };
    for (const d of pol.obligations || []) loop(d, 'duty');
    for (const pm of pol.permissions || []) loop(pm, regelSoort(pm, false));
    for (const pb of pol.prohibitions || []) loop(pb, 'verbod');
  }
  return ix;
}

// De index hangt aan het MODEL, niet aan de render: hem per paneelrij opnieuw
// bouwen zou het corpus per hover aflopen. Een gewone cache volstaat — het model
// is een onveranderlijk object dat bij elke lading (en elke taalwissel) wordt
// vervangen, dus identiteit is hier een geldige sleutel.
let laatsteModel: DekkingsModel | null = null;
let laatsteIndex = new Map<string, Ingang>();

/** De opzoektabel van het huidige model. Leest `model()`, dus reactief. */
export function invullingIndex(): Map<string, Ingang> {
  const m = model() as unknown as DekkingsModel | null;
  if (m !== laatsteModel) { laatsteModel = m; laatsteIndex = bouwInvullingIndex(m); }
  return laatsteIndex;
}

// ============================================================================
// De twee richtingen
// ============================================================================
// De functienamen zeggen WAT de richting is, niet waar zij in het paneel staat:
// de stand is een weergavebesluit (zie InvullingPaneel) en is al een keer
// gedraaid.

/** De titel van een policy uit het model, voor de subkoppen in het paneel. */
function policyTitel(iri: string | null | undefined, m: DekkingsModel | null): string | null {
  if (!iri || !m) return null;
  const pol = allePolicies(m).find((x) => x.iri === iri);
  return (pol && pol.title) || curie(iri) || null;
}

/** WORDT INGEVULD DOOR (↑): wat werkt dit element uit? Precies de stappen die
 *  het model al kent (parse.js/coverageNext) — de weergave verzint niets bij.
 *    verplichting -> de voorwaarde(n) die haar invullen
 *    voorwaarde   -> de conformsToPolicy-rij die haar afdwingt
 *    regel        -> haar eigen conformsToPolicy-rij
 *    conformsTo   -> niets: het einde van de keten (het artefact is geen
 *                    ketenknoop meer, het staat in de uitklap van deze rij) */
export function wordtIngevuldDoor(
  desc: Ingang | null, scope: string | null, m: DekkingsModel | null,
): Blok[] {
  if (!desc) return [];
  if (desc.type === 'conforms') return [];
  if (desc.type === 'condition') {
    return [{
      title: null,
      refs: coverageNext(desc.constraint).map((x: any) => x.targetRef).filter(Boolean),
    }];
  }
  const alle = coverageNext(desc.rule).filter((x: any) => x && x.targetRef);
  if (!alle.length) return [];
  const eigen = scope ? alle.filter((x: any) => (x.policies || []).includes(scope)) : [];
  if (eigen.length) return [{ title: null, refs: eigen.map((x: any) => x.targetRef) }];
  // GEEN SCHAKEL IN DEZE POLICY — dat is de kaart waar de plicht is
  // GEDEFINIEERD (de stelselset): daar werkt zij zelf niets uit, elders wel.
  // Dan tonen we alles, en dan MOET de herkomst erbij: vier keer dezelfde
  // voorwaarde onder elkaar zonder te zeggen uit welke beleidsset zij komt, was
  // precies de klacht — je zag de relatie wel, maar niet waarheen.
  const perSet = new Map<string | null, string[]>();
  for (const x of alle as any[]) {
    for (const pol of ((x.policies || []).length ? x.policies : [null]) as (string | null)[]) {
      const titel = policyTitel(pol, m);
      if (!perSet.has(titel)) perSet.set(titel, []);
      const refs = perSet.get(titel)!;
      if (!refs.includes(x.targetRef)) refs.push(x.targetRef);
    }
  }
  return [...perSet].map(([title, refs]) => ({ title, refs }));
}

/** De keten-ingangen van één regel, GEFILTERD op de kaart waar hij staat. Een
 *  gedeelde stelselplicht staat in drie Sets; zonder filter zou elke kaart alle
 *  uitwerkingen van alle beslispunten opsommen. Staat er in DEZE policy een
 *  schakel, dan spreekt alleen die; staat er geen (de eigenaar-kaart van de
 *  plicht), dan spreken ze allemaal — daar is het totaalbeeld de bedoeling. */
function viaIngangen(rule: DekkingsRegel | undefined, scope: string | null): ViaSchakel[] {
  const via = (rule && rule.coverage && rule.coverage.via) || [];
  if (!scope || !via.length) return via;
  const eigen = via.filter((v) => (v.policies || []).includes(scope));
  return eigen.length ? eigen : via;
}

/** De HERKOMST van de stelselplichten van één beleidsset: plicht-IRI -> de
 *  ouderpolicy waaruit zij is overgenomen. Zonder dit staat een geërfde plicht
 *  in het paneel als een plicht van deze set, terwijl zij op de koppelvlak-set
 *  hoort. */
function plichtHerkomst(scope: string | null, m: DekkingsModel | null): Map<string, string> {
  const map = new Map<string, string>();
  if (!scope || !m) return map;
  const pol = allePolicies(m).find((x) => x.iri === scope);
  for (const { duty, from } of setPlichten(pol)) {
    if (duty && duty.iri && from) map.set(duty.iri, from);
  }
  return map;
}

/** De set-niveau verplichtingen die DEZE knoop invult en die op DEZE regel van
 *  toepassing zijn. `direct` zegt of de knoop de plicht zelf realiseert; zo
 *  niet, dan komt zij hier alleen binnen omdat een VOORWAARDE van deze regel
 *  haar uitwerkt, en dan hoort die tussenstap in beeld. */
function vouwPlichten(
  ingangen: SetPlicht[] | undefined, nodeIri: string | null | undefined, scope: string | null,
): { duty: DekkingsRegel; from: string | null; direct: boolean; via: ViaSchakel[] }[] {
  const uit = [];
  for (const { duty, from } of ingangen || []) {
    const direct = (duty.coveredBy || []).some((a) => a.iri === nodeIri);
    const via = viaIngangen(duty, scope)
      .filter((v) => v.artefacts.some((a) => a.iri === nodeIri));
    if (!direct && !via.length) continue;
    uit.push({ duty, from, direct, via: direct ? [] : via });
  }
  return uit;
}

/** De naam van een voorwaarde in één woord, voor de "via voorwaarde ‘…’"-
 *  notitie: haar rdfs:label, anders de grootheid waar zij over gaat. */
function voorwaardeWoord(c: Voorwaarde | undefined): string | null {
  if (!c) return null;
  if (c.label) return c.label;
  const slot = c.slots && c.slots.left;
  return (slot && slot.text) || c.sentence || null;
}

/** De gedekte en ongedekte voorwaarden van een regel, IN DE VOLGORDE VAN DE
 *  KAART (coverageRuleSummary in de viewer). */
function regelSamenvatting(rule: DekkingsRegel | undefined) {
  const cov = rule && rule.coverage;
  if (!cov) return null;
  const isGedekt = new Set(cov.conditions.keys());
  const isOngedekt = new Set(cov.uncovered || []);
  const gedekt: Voorwaarde[] = [];
  const ongedekt: Voorwaarde[] = [];
  const gezien = new Set<string>();
  for (const c of eigenVoorwaarden(rule!)) {
    if (!c || !c.iri || gezien.has(c.iri)) continue;
    if (isGedekt.has(c.iri)) { gezien.add(c.iri); gedekt.push(c); }
    else if (isOngedekt.has(c.iri)) { gezien.add(c.iri); ongedekt.push(c); }
  }
  return { cov, gedekt, ongedekt };
}

/** GEEFT INVULLING AAN (↓): wat vult dit element zelf in?
 *    voorwaarde   -> de verplichting/regel die zij uitwerkt (coverage.via)
 *    conformsTo   -> de regel, haar afgedwongen voorwaarden en de
 *                    stelselverplichtingen die deze knoop invult
 *    regel        -> niets: een regel vult zelf niets in, zij wordt ingevuld */
export function geeftInvullingAan(
  desc: Ingang | null, scope: string | null, m: DekkingsModel | null,
): Blok[] {
  if (!desc) return [];
  if (desc.type === 'condition') {
    const refs = (desc.constraint!.fulfils || []).map((r) => r.iri).filter(Boolean);
    // De plicht die deze voorwaarde uitwerkt staat vaak op de OUDERSET (een
    // stelselplicht via odrl:inheritFrom). Dat hoort op de rij te staan: zonder
    // die herkomst leest zij als een plicht van deze set.
    const van = plichtHerkomst(scope, m);
    const notes: Record<string, string> = {};
    for (const r of refs) if (van.has(r)) notes[r] = tekst('cov.dutyFrom', { parent: van.get(r) });
    return [{ title: null, refs, notes }];
  }
  if (desc.type !== 'conforms') return [];

  const refs: string[] = [];
  const sum = regelSamenvatting(desc.rule);
  // DE RIJ LEEST HAAR EIGEN LINKS: draagt het anker zelf prov:wasDerivedFrom
  // (de Vlierdam-vorm, waarin de realisatielinks in de policy staan en niet bij
  // het artefact), dan zegt `realises` letterlijk wat DEZE rij uitwerkt.
  // Ontbreekt het lijstje (een blank anker, of de oudere vorm waarin het
  // ARTEFACT de afzender is), dan blijft de afleiding uit de dekking staan.
  const realises = desc.constraint && desc.constraint.realises;
  const noemt = (iri: string) => !realises || realises.includes(iri);
  if (sum && sum.cov.rule.length && desc.rule!.iri && noemt(desc.rule!.iri)) refs.push(desc.rule!.iri);
  if (sum) {
    for (const c of sum.gedekt) {
      if (c.iri && noemt(c.iri) && !refs.includes(c.iri)) refs.push(c.iri);
    }
  }
  const eigen = scope || (desc.scopes[0] || {}).iri || null;
  const blokken: Blok[] = [{ title: null, refs }];
  // DE STELSELPLICHTEN APART, met hun herkomst. Ze horen niet bij de regel en
  // haar eigen voorwaarden: ze gelden voor élke regel van de beleidsset, en deze
  // knoop vult ze soms rechtstreeks in en soms VIA een voorwaarde van déze
  // regel. Dat verschil is de hele reden dat de keten leesbaar is.
  const plichten: string[] = [];
  const notes: Record<string, string> = {};
  for (const { duty, from, via, direct } of vouwPlichten(desc.plichten, desc.nodeIri, eigen)) {
    if (!duty.iri || plichten.includes(duty.iri)) continue;
    plichten.push(duty.iri);
    const delen: string[] = [];
    if (from) delen.push(tekst('cov.dutyFrom', { parent: from }));
    // DE TUSSENSTAP IS NIET OPTIONEEL. Een plicht die deze knoop alleen VIA een
    // voorwaarde invult, mag nooit als kale rij tussen de rechtstreekse
    // invullingen staan: dan leest zij als een realisatieclaim die in de data
    // niet staat. Ontdubbelen hoort erbij (dezelfde voorwaarde kan via meer
    // artefacten schakelen), en kan de tussenstap niet bij naam worden genoemd,
    // dan zegt de rij nog steeds DÁT er een stap tussen zit.
    if (!direct) {
      const namen = [...new Set(via.map((v) => voorwaardeWoord(v.constraint)).filter(Boolean))];
      for (const naam of namen) delen.push(tekst('cov.dutyViaCond', { cond: naam }));
      if (!namen.length) delen.push(tekst('cov.dutyViaCondAnon'));
    }
    if (delen.length) notes[duty.iri] = delen.join(' · ');
  }
  if (plichten.length) blokken.push({ title: tekst('fill.duties'), refs: plichten, notes });
  return blokken;
}

/** "Niet afgedwongen": de benoemde voorwaarden van deze regel die geen enkel
 *  artefact uitwerkt, met de tweedeling die het model meelevert (ongemarkeerd ->
 *  hier is iets blijven liggen; organisatorisch geborgd -> er valt niets uit te
 *  werken). Eerlijke leegte, geen bevinding. */
export function nietAfgedwongen(
  desc: Ingang | null,
): { ongedekt: Voorwaarde[]; redenen: Record<string, string> } | null {
  const rule = desc && (desc.type === 'rule' || desc.type === 'conforms') ? desc.rule : null;
  if (!rule) return null;
  const sum = regelSamenvatting(rule);
  if (!sum || !sum.ongedekt.length) return null;
  return { ongedekt: sum.ongedekt, redenen: sum.cov.uncoveredReasons || {} };
}

/** De naam van een regel zoals haar eigen rij hem draagt: eigen titel, anders
 *  het actie-label (bij een verplichting is `action` een string, bij een
 *  toestemming een object), anders het soortwoord. */
export function regelTitel(rule: DekkingsRegel | undefined, kind: RegelSoort): string {
  if (!rule) return '';
  const act = rule.action;
  const actWoord = (act && typeof act === 'object') ? act.label : act;
  return rule.title || rule.label || actWoord
    || tekst(kind === 'duty' ? 'title.duty' : 'title.permission');
}

/** De dekkingsstand van een element: amber zodra er iets ontbreekt. */
function dekkingsStand(desc: Ingang | undefined): 'full' | 'partial' {
  if (desc && desc.type === 'rule') {
    const cov = desc.rule && desc.rule.coverage;
    return cov && cov.status === 'partial' ? 'partial' : 'full';
  }
  return 'full';
}

// ============================================================================
// De weergave adresseren: data-ref
// ============================================================================

const REF_HL = 'is-ref-hl';
const REF_BOX = 'is-ref-box';
const REF_PULSE = 'is-ref-pulse';
/** Hoe lang het doel oplicht na aankomst — lang genoeg om te zien waar je
 *  landde, kort genoeg om niet als selectie te blijven staan. */
const HL_MS = 1800;

/** De hoofdkolom van de app: daarbinnen staat de weergave. Zonder schil (een
 *  testpagina, een losse mount) is het document zelf het zoekgebied. */
function zoekwortel(): HTMLElement | null {
  if (typeof document === 'undefined') return null;
  return document.getElementById('app-hoofd') || document.body || null;
}

// Handmatig aflopen in plaats van querySelectorAll: een attribuutselector met
// een IRI erin vraagt om ontsnapping, en dit leest precies zo makkelijk.
function refKnopen(root: Element | null, attr: string, ref: string): HTMLElement[] {
  const uit: HTMLElement[] = [];
  const loop = (n: Element) => {
    for (const c of Array.from(n.children || [])) {
      if (c.getAttribute && c.getAttribute(attr) === ref) uit.push(c as HTMLElement);
      loop(c);
    }
  };
  if (root) loop(root);
  return uit;
}

/** Waar een ref in het document te vinden is: eerst de rijen die hem letterlijk
 *  dragen, anders — voor een artefact — de conformsToPolicy-rijen die ernaar
 *  verwijzen (data-art). */
function refDoelen(root: Element | null, ref: string): HTMLElement[] {
  const direct = refKnopen(root, 'data-ref', ref);
  return direct.length ? direct : refKnopen(root, 'data-art', ref);
}

/** De KAART van één beleidsset in de weergave. Nodig omdat het paneel naast het
 *  document staat: een rij in het paneel heeft geen DOM-ouder in de kaart waar
 *  zij vandaan komt, dus alleen de SCOPE van het paneel zegt wat "dezelfde
 *  kaart" hier betekent. Eén gedeelde knoop staat namelijk op meer dan één plek
 *  — een stelselplicht op haar eigen kaart én in de "Geërfd van …"-vouw van elk
 *  beslispunt dat haar overneemt, allemaal met dezelfde data-ref. */
function kaartVanScope(scope: string | null): HTMLElement | null {
  const wortel = zoekwortel();
  if (!wortel || !scope) return null;
  for (const n of refKnopen(wortel, 'data-iri', scope)) {
    if (/\b(set-card|offer-group|agr-group)\b/.test(String(n.className || ''))) return n;
  }
  return null;
}

/** De buitenste DICHTE <details> boven een knoop: daarbinnen is niets zichtbaar
 *  behalve de <summary> zelf. Teruggegeven wordt die kop — de rij die de lezer
 *  wél ziet. null als de knoop gewoon zichtbaar is. */
function dichteVouwKop(node: Element | null): HTMLElement | null {
  const tag = (n: Element | null) => String((n && n.tagName) || '').toLowerCase();
  let box: HTMLElement | null = null;
  for (let cur: Element | null = node; cur && cur.parentElement; cur = cur.parentElement) {
    const p = cur.parentElement;
    if (tag(p) === 'details' && !(p as HTMLDetailsElement).open && tag(cur) !== 'summary') {
      box = p as HTMLElement;
    }
  }
  if (!box) return null;
  for (const c of Array.from(box.children)) if (tag(c) === 'summary') return c as HTMLElement;
  return box;
}

/** Staat dit element in het scrollvenster, of erboven/eronder? Zonder MEETBARE
 *  rechthoek (jsdom levert overal nullen) gaan we uit van 'in': liever geen
 *  indicator dan een verkeerde. */
function ankerPositie(node: HTMLElement): 'in' | 'above' | 'below' {
  if (!node || typeof node.getBoundingClientRect !== 'function') return 'in';
  const r = node.getBoundingClientRect();
  const hoogte = (typeof window !== 'undefined' && window.innerHeight) || 0;
  if (!r || !hoogte) return 'in';
  if (!r.width && !r.height && !r.top && !r.bottom) return 'in';
  if (r.bottom <= 0) return 'above';
  if (r.top >= hoogte) return 'below';
  return 'in';
}

/** Wat er voor deze ref aangewezen moet worden. Van meer bronnen met dezelfde
 *  ref wint een ZICHTBARE; van meer voorkomens wint die in de kaart van de
 *  beleidsset waar het paneel op staat (anders wijst de hover een andere rij aan
 *  dan de klik erna). */
function zichtbaarAnker(ref: string, scope: string | null) {
  const wortel = zoekwortel();
  if (!wortel || !ref) return null;
  const kaart = kaartVanScope(scope);
  const eigen = kaart ? refDoelen(kaart, ref) : [];
  const knopen = eigen.length ? eigen : refDoelen(wortel, ref);
  if (!knopen.length) return null;
  const vrij = knopen.find((n) => !dichteVouwKop(n));
  const node = vrij || knopen[0];
  const box = vrij ? null : dichteVouwKop(node);
  const element = box || node;
  return { element, exact: !box, positie: ankerPositie(element) };
}

// Wat er nú opgelicht is — precies terugdraaien is nodig omdat de markering op
// een OMHULSEL kan staan dat de ref zelf niet draagt.
let opgelicht: HTMLElement[] = [];
const [randHint, zetRandHint] = createSignal<'above' | 'below' | null>(null);

/** ALLE HOVER-SPOREN WEG: de markering op de bron én de rand-pulsbalk. Eigen
 *  functie omdat niet alleen mouseleave hem nodig heeft: een SPRONG ruimt ze op
 *  vóór hij vertrekt, en het paneel doet het bij elke wissel — beide gevallen
 *  waarin de mouseleave nooit komt omdat de rij onder de muis vandaan verdwijnt. */
export function wisMarkeringen(): void {
  for (const n of opgelicht) {
    if (n && n.classList) { n.classList.remove(REF_HL); n.classList.remove(REF_BOX); }
  }
  opgelicht = [];
  zetRandHint(null);
}

function markeer(ref: string, aan: boolean, scope: string | null): void {
  wisMarkeringen();
  if (!aan) return;
  const anker = zichtbaarAnker(ref, scope);
  if (!anker) return;
  if (anker.exact) {
    // Alle zichtbare voorkomens van de bron — binnen de kaart van de scope als
    // de knoop daar staat.
    const wortel = kaartVanScope(scope) || zoekwortel();
    const inScope = refDoelen(wortel, ref);
    const knopen = inScope.length ? inScope : refDoelen(zoekwortel(), ref);
    for (const n of knopen) {
      if (dichteVouwKop(n)) continue;
      n.classList.add(REF_HL);
      opgelicht.push(n);
    }
  } else {
    anker.element.classList.add(REF_HL);
    anker.element.classList.add(REF_BOX);
    opgelicht.push(anker.element);
  }
  if (anker.positie !== 'in') zetRandHint(anker.positie);
}

function magBewegen(): boolean {
  return !(typeof window !== 'undefined' && typeof window.matchMedia === 'function'
    && window.matchMedia('(prefers-reduced-motion: reduce)').matches);
}

/** DE WEG NAAR DE BRON VRIJMAKEN: elke dichte <details> boven het doel open —
 *  de kaart, de geërfd-vouw, de ledenlijst. Van buiten naar binnen, want een
 *  kind meet pas als zijn ouder open is. */
function openPadNaar(doel: HTMLElement): void {
  const pad: HTMLElement[] = [];
  for (let cur: HTMLElement | null = doel; cur; cur = cur.parentElement) pad.push(cur);
  pad.reverse();
  for (const n of pad) {
    if (String(n.tagName || '').toLowerCase() !== 'details') continue;
    (n as HTMLDetailsElement).open = true;
    n.setAttribute('open', '');
  }
  // De conformsToPolicy-rij is het EINDE van de keten, en het artefact staat in
  // háár uitklap. Wie er vanuit het paneel naartoe springt, zoekt meestal juist
  // dat artefact — dus klapt de sprong die ene vouw meteen open.
  for (const c of Array.from(doel.children)) {
    if (c.classList && c.classList.contains('art-fold')) {
      (c as HTMLDetailsElement).open = true;
      c.setAttribute('open', '');
    }
  }
}

function flits(node: HTMLElement, klassen: string[]): void {
  for (const k of klassen) node.classList.add(k);
  setTimeout(() => {
    if (!node.classList) return;
    for (const k of klassen) node.classList.remove(k);
  }, HL_MS);
}

// De sprong-haak van de app: een kaartenlijst moet eerst haar SECTIE openen
// voordat er iets te scrollen valt (taak 3). Staat hij niet, dan doet het paneel
// de sprong zelf op het data-ref-contract — precies zoals de bevroren viewer.
let springHaak: ((ref: string, scope: string | null) => boolean | void) | null = null;

/** De sprong vanuit een paneelrij. */
function spring(ref: string, scope: string | null): void {
  if (springHaak) { springHaak(ref, scope); return; }
  springNaarRef(ref, scope);
}

/** DE SPRONG (het → in het paneel): de weg vrijmaken, het DOCUMENT ernaartoe
 *  scrollen, de bron kort laten pulsen — en het paneel gewoon open laten staan.
 *  `false` als de weergave de ref niet kent; de aanroeper laat de lezer dan
 *  staan waar hij stond. */
export function springNaarRef(ref: string, scope: string | null = null): boolean {
  // EERST DE HOVER-SPOREN WEG: die horen bij "de muis staat op deze paneelrij",
  // en zodra je klikt is dat voorbij.
  wisMarkeringen();
  const kaart = kaartVanScope(scope);
  const eigen = kaart ? refDoelen(kaart, ref) : [];
  const doel = eigen[0] || refDoelen(zoekwortel(), ref)[0];
  if (!doel) return false;
  // VOLGORDE: eerst het pad openklappen, dán scrollen, en pas bij aankomst de
  // puls. Andersom mikt de scroll op een positie die het openklappen daarna
  // verschuift.
  openPadNaar(doel);
  if (typeof doel.scrollIntoView === 'function') {
    doel.scrollIntoView({ behavior: magBewegen() ? 'smooth' : 'auto', block: 'start' });
  }
  flits(doel, [REF_HL, REF_PULSE]);
  return true;
}

// ============================================================================
// De paneelstand
// ============================================================================

interface PaneelStand { ref: string; scope: string | null }

const [paneelStand, zetPaneelStand] = createSignal<PaneelStand | null>(null);

/** De stand van het paneel: `null` als het dicht is. */
export const invullingStand = paneelStand;

// De plek waar de gekozen rij STOND, voor de overgang (zie Rij/flip). Meten
// gebeurt vóór de wissel: daarna bestaat de oude rij niet meer.
let vanRect: DOMRect | null = null;

function rechthoek(node: Element | null | undefined): DOMRect | null {
  if (!node || typeof node.getBoundingClientRect !== 'function') return null;
  try {
    const r = node.getBoundingClientRect();
    return r && (r.width || r.height) ? r : null;
  } catch { return null; }
}

/** Het paneel openen, of — als het al openstaat — verzetten naar een ander
 *  element. `van` is de paneelrij waar de lezer vandaan kwam; die schuift dan
 *  zichtbaar naar het centrale vlak. */
export function openInvulling(
  ref: string, scope: string | null = null, opties: { van?: Element | null } = {},
): void {
  if (!ref) return;
  vanRect = rechthoek(opties.van || null);
  wisMarkeringen();
  zetPaneelStand({ ref, scope: scope || null });
}

/** Het paneel sluiten (✕, Escape, of een aanroeper die de stand opruimt). */
export function sluitInvulling(): void {
  vanRect = null;
  wisMarkeringen();
  zetPaneelStand(null);
}

// De stand van de twee vouwen hoort bij de MODUS, niet bij het element: wie een
// richting dichtklapt en dan een ander element opent, wil hem dicht houden. In
// een gewone module-variabele, dus sessiegebonden — en zo overleeft de stand ook
// een taalwissel. Standaard beide OPEN: de keten is de inhoud van het paneel.
const [bovenOpen, zetBovenOpen] = createSignal(true);
const [onderOpen, zetOnderOpen] = createSignal(true);

// ============================================================================
// De componenten
// ============================================================================

/** HET RADERWIEL: de opener van het paneel, op elk element dat wordt ingevuld.
 *  Exact dezelfde ronde knop als de ⌕-verkenknop (klasse `verken-btn`) — twee
 *  knoppen naast elkaar op één rij horen één familie te zijn. KLEUR = STAND:
 *  groen-gedempt als alles is ingevuld, amber als er iets ontbreekt. */
export function InvullingKnop(props: {
  /** De `data-ref` van het element waarop het paneel moet gaan staan. Niet
   *  `ref`: dat is in Solid de gereserveerde naam voor een element-handle. */
  doel: string; scope?: string | null; status?: 'full' | 'partial';
}): JSX.Element {
  const status = () => props.status ?? dekkingsStand(invullingIndex().get(props.doel));
  const hint = () => tekst('fill.gearTitle');
  return (
    <Show when={props.doel}>
      <button
        type="button"
        class={'verken-btn cov-gear cov-status ' + status()}
        title={hint()} aria-label={hint()}
        onClick={(e) => {
          e.preventDefault();
          e.stopPropagation();
          openInvulling(props.doel, props.scope ?? null, { van: e.currentTarget });
        }}
      >{'⚙'}</button>
    </Show>
  );
}

/** De naam van het artefact achter een conformsToPolicy-rij. */
function artefactNaam(iri: string | null | undefined): string {
  const m = model() as unknown as DekkingsModel | null;
  const alle = [...((m && m.artifacts) || []), ...((m && m.bundles) || [])];
  const art = alle.find((a) => a.iri === iri);
  return (art && art.title) || curie(iri || '') || String(iri || '');
}

/** De chip-rij van een conformsToPolicy-anker: de vaste ODRL-AP-NL-zin met de
 *  naam van het artefact als rechterwaarde. Draagt de rij die vorm NIET (een
 *  borging met alleen de dpv:TechnicalMeasure-marker), dan zou de zin liegen en
 *  tonen we gewoon haar eigen chips. */
function ConformsInhoud(props: { c: Voorwaarde }): JSX.Element {
  return (
    <Show when={props.c.conformsOp && props.c.conformsTo} fallback={<VoorwaardeInhoud c={props.c} />}>
      <span class="c-chips">
        <span class="c-slot left">{tekst('conforms.left')}</span>
        <ChipRuimte />
        <span class="c-slot op">{tekst('conforms.op')}</span>
        <ChipRuimte />
        <span class="c-slot right">{artefactNaam(props.c.conformsTo)}</span>
      </span>
    </Show>
  );
}

/** De inhoud van één rij: wat voor element het is, in de vorm die het document
 *  er ook aan geeft. */
function RijInhoud(props: { desc: Ingang }): JSX.Element {
  return (
    <Switch>
      <Match when={props.desc.type === 'rule'}>
        <RegelBadge soort={props.desc.kind} />
        <span class="op-name">{regelTitel(props.desc.rule, props.desc.kind)}</span>
      </Match>
      <Match when={props.desc.type === 'condition'}>
        <VoorwaardeInhoud c={props.desc.constraint!} />
        <Show when={props.desc.constraint!.label}>
          <span class="c-note muted">{props.desc.constraint!.label}</span>
        </Show>
      </Match>
      <Match when={props.desc.type === 'conforms'}>
        <ConformsInhoud c={props.desc.constraint!} />
      </Match>
    </Switch>
  );
}

/** DE OVERGANG bij het verzetten van het paneel: meet waar de rij stond, zet
 *  haar met een transform terug op die plek en laat de transform naar nul lopen
 *  (FLIP). Geen layout-animatie, dus geen gehannes met de rest van het paneel.
 *  Zonder meetbare rechthoeken (jsdom) of bij reduced-motion gebeurt er niets. */
const FLIP_MS = 200;
function flip(node: HTMLElement, van: DOMRect | null): void {
  if (!node || !van || !magBewegen()) return;
  const naar = rechthoek(node);
  if (!naar) return;
  const dx = van.left - naar.left;
  const dy = van.top - naar.top;
  if (!dx && !dy) return;
  node.style.transition = 'none';
  node.style.transform = `translate(${dx}px, ${dy}px)`;
  const los = () => {
    node.style.transition = `transform ${FLIP_MS}ms ease-out`;
    node.style.transform = 'translate(0, 0)';
    setTimeout(() => {
      if (!node.style) return;
      node.style.transition = '';
      node.style.transform = '';
    }, FLIP_MS + 60);
  };
  // Twee frames: één om de beginstand te laten landen, één om ervan weg te
  // animeren. In één frame ziet de browser alleen de eindstand.
  if (typeof requestAnimationFrame === 'function') {
    requestAnimationFrame(() => requestAnimationFrame(los));
  } else setTimeout(los, 16);
}

/** Eén rij in een blok: de duplicaat-render van het element plus de uitgangen.
 *  KLIKKEN: enkelklik = het → (het DOCUMENT gaat erheen, het paneel blijft
 *  staan), dubbelklik = het ⚙ (het PANEEL gaat erheen). De HUIDIGE rij draagt
 *  die uitgangen niet — naar jezelf springen doet niets — maar houdt wél het ⌕. */
function Rij(props: {
  doel: string; scope: string | null; huidig?: boolean; note?: string | null;
}): JSX.Element {
  const desc = () => invullingIndex().get(props.doel);
  const verkenDoel = () => {
    const d = desc();
    if (!d) return null;
    if (d.type === 'rule') return (d.rule && (d.rule.iri || (d.rule as any).term)) || null;
    const c = d.constraint;
    return (c && (c.term || c.iri)) || null;
  };
  const titel = () => {
    const c = desc()?.constraint;
    return [c && c.label, c && c.comment].filter(Boolean).join(' — ') || undefined;
  };
  return (
    <li
      class={'fill-row' + (props.huidig ? ' is-current' : '')}
      data-ref={props.doel} tabindex="0" title={titel()}
      ref={(el) => { if (props.huidig) flip(el, vanRect); }}
      onMouseEnter={() => markeer(props.doel, true, props.scope)}
      onMouseLeave={() => markeer(props.doel, false, props.scope)}
      onFocusIn={() => markeer(props.doel, true, props.scope)}
      onFocusOut={() => markeer(props.doel, false, props.scope)}
      onClick={(e) => {
        if (props.huidig || knopGeraakt(e)) return;
        // De TWEEDE klik van een dubbelklik springt niet nóg eens: die komt hier
        // binnen met detail 2, en zonder deze regel scrolde het document twee
        // keer achter elkaar tijdens één dubbelklik-gebaar.
        if ((e.detail || 1) > 1) return;
        e.preventDefault();
        spring(props.doel, props.scope);
      }}
      onDblClick={(e) => {
        if (props.huidig || knopGeraakt(e)) return;
        e.preventDefault();
        e.stopPropagation();
        openInvulling(props.doel, props.scope, { van: e.currentTarget });
      }}
    >
      {/* Inhoud links (mag afbreken), uitgangen rechts (nooit): anders zakt het
          raderwiel bij elke lange rij naar een eigen regel. */}
      <span class="fill-content">
        <Show
          when={desc()}
          fallback={<span class="muted">{curie(props.doel) || props.doel}</span>}
        >
          <RijInhoud desc={desc()!} />
        </Show>
        {/* De herkomst-notitie ("overgenomen van …", "via voorwaarde ‘…’"):
            klein en gedempt ónder de inhoud, niet ernaast — de rij is al vol. */}
        <Show when={props.note}>
          <span class="fill-note muted">{props.note}</span>
        </Show>
      </span>
      <Show when={desc()}>
        <span class="fill-acts">
          <Show when={!props.huidig}>
            <button
              type="button" class="fill-jump"
              title={tekst('fill.jump')} aria-label={tekst('fill.jump')}
              onClick={(e) => {
                e.preventDefault(); e.stopPropagation();
                spring(props.doel, props.scope);
              }}
            >{'→'}</button>
          </Show>
          <VerkenKnop doel={verkenDoel()} />
          <Show when={!props.huidig}>
            <InvullingKnop doel={props.doel} scope={props.scope} status={dekkingsStand(desc())} />
          </Show>
        </span>
      </Show>
    </li>
  );
}

/** Kwam de klik op een van de knoppen in de rij terecht? Die hebben hun eigen
 *  klik al afgehandeld. */
function knopGeraakt(e: Event): boolean {
  for (let cur = e.target as Element | null; cur; cur = cur.parentElement) {
    if (String(cur.tagName || '').toLowerCase() === 'button') return true;
    if (String(cur.tagName || '').toLowerCase() === 'a') return true;
  }
  return false;
}

/** Eén richting: de subkoppen en de rijen. De KOP van het blok staat niet hier
 *  maar op de rand van het grijze vlak (zie VouwRand). */
function BlokRijen(props: {
  blokken: Blok[]; scope: string | null; cls: string; dicht?: boolean;
}): JSX.Element {
  return (
    <div class={'fill-block ' + props.cls} hidden={props.dicht}>
      <For each={props.blokken}>{(b) => (
        <>
          <Show when={b.title}>
            <p class="fill-subhead muted">{b.title}</p>
          </Show>
          <ul class="clean fill-list">
            <For each={b.refs}>{(r) => (
              <Rij doel={r} scope={props.scope} note={(b.notes || {})[r] || null} />
            )}</For>
          </ul>
        </>
      )}</For>
    </div>
  );
}

/** Het randlabel op de rand van het grijze vlak: klikken klapt het bijbehorende
 *  blok open of dicht. DE CHEVRON KOMT UIT CSS (::after op .is-foldable,
 *  gestuurd door aria-expanded) — een echt element zou in de TEKST van het
 *  label gaan zitten, en dat label is een leesbare zin, geen knoppenbalk. */
function VouwRand(props: {
  label: string; cls: string; open: () => boolean; zet: (v: boolean) => void;
}): JSX.Element {
  const omklappen = () => props.zet(!props.open());
  return (
    <p
      class={'fill-edge ' + props.cls + ' is-foldable'}
      role="button" tabindex="0" aria-expanded={props.open()}
      onClick={omklappen}
      onKeyDown={(e) => {
        if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); omklappen(); }
      }}
    >{props.label}</p>
  );
}

/** HET PANEEL. Eén exemplaar per app; hij staat altijd gemonteerd (ook dicht),
 *  want zijn Escape-laag en zijn markeringen horen bij de pagina, niet bij een
 *  geopend paneel. */
export function InvullingPaneel(props: {
  /** De sprong naar het document. Standaard doet het paneel hem zelf op het
   *  data-ref-contract; een app met een kaartenlijst die eerst haar sectie moet
   *  openen (taak 3) geeft hier haar eigen `spring` mee. */
  onSpring?: (ref: string, scope: string | null) => boolean | void;
}): JSX.Element {
  const paneel = () => paneelStand();
  const desc = () => {
    const s = paneel();
    return s ? invullingIndex().get(s.ref) : undefined;
  };
  // De eigen beleidsset van dit element: de meegegeven scope, anders de eerste
  // herkomst uit de index.
  const eigen = () => {
    const s = paneel();
    return (s && s.scope) || (desc()?.scopes[0] || {}).iri || null;
  };
  const m = () => model() as unknown as DekkingsModel | null;
  // De taal reist mee: de notities ("via voorwaarde …") komen uit de
  // stringtabel van de modellaag, en die is zelf niet reactief.
  const boven = createMemo(() => {
    void weergave.lang;
    return wordtIngevuldDoor(desc() || null, eigen(), m()).filter((b) => b.refs.length);
  });
  const onder = createMemo(() => {
    void weergave.lang;
    return geeftInvullingAan(desc() || null, eigen(), m()).filter((b) => b.refs.length);
  });
  const ongedekt = createMemo(() => nietAfgedwongen(desc() || null));
  const herkomst = () => (desc()?.scopes || []).map((sc) => sc.title).filter(Boolean);

  // Het paneel duwt het document opzij zolang het openstaat.
  createEffect(() => {
    if (typeof document === 'undefined' || !document.body) return;
    document.body.classList[paneel() ? 'add' : 'remove']('panel-open');
  });
  // Elke wissel ruimt de markeringen op: de rij waar de muis op stond verdwijnt,
  // dus haar mouseleave komt nooit.
  createEffect(() => { void paneel(); wisMarkeringen(); });

  // --- De Escape-laag -------------------------------------------------------
  // GELAAGD, IN DE CAPTURE-FASE (verbetering t.o.v. de bevroren viewer). Daar
  // hingen paneel en zijnav allebei in de bubbelfase aan het document, en sloot
  // één Escape ze ALLEBEI tegelijk — de lezer verloor zijn zijnav omdat hij het
  // paneel dichtdeed. De capture-fase loopt vóór elke bubbel-luisteraar, dus het
  // paneel — de bovenste laag — kan de toets opmaken en met
  // stopImmediatePropagation tegenhouden dat de zijnav hem óók nog krijgt.
  //
  // UITZONDERING: staat de focus in een INVOERVELD, dan is de Escape van dat
  // veld. Zo houdt de zijnav zijn tweetraps-Escape (eerst het filter leegmaken,
  // pas daarna de pane) — het paneel is dan niet de bovenste laag, het typen is
  // dat.
  function opToets(e: KeyboardEvent): void {
    if (e.key !== 'Escape' || !paneelStand()) return;
    const a = typeof document !== 'undefined' ? document.activeElement : null;
    const tag = String((a && a.tagName) || '').toLowerCase();
    if (tag === 'input' || tag === 'textarea' || (a as HTMLElement | null)?.isContentEditable) return;
    sluitInvulling();
    e.preventDefault();
    if (e.stopImmediatePropagation) e.stopImmediatePropagation();
    else e.stopPropagation();
  }
  if (typeof document !== 'undefined' && document.addEventListener) {
    document.addEventListener('keydown', opToets, true);
    onCleanup(() => {
      document.removeEventListener('keydown', opToets, true);
      document.body?.classList.remove('panel-open');
      wisMarkeringen();
    });
  }

  // De sprong-haak van de app (taak 3: eerst de sectie openen, dán scrollen).
  // Zolang niemand hem meegeeft, springt het paneel zelf op het data-ref-contract.
  springHaak = props.onSpring || null;
  onCleanup(() => { springHaak = null; });

  return (
    <>
      <Show when={paneel()}>{(s) => (
        <aside class="insp-overlay" role="dialog" aria-label={tekst('fill.title')}>
          <div class="insp-head">
            <span class="insp-title">{tekst('fill.title')}</span>
            <button
              class="insp-close" type="button" title={tekst('panel.close')}
              onClick={() => sluitInvulling()}
            >{'✕'}</button>
          </div>
          <div class="insp-body insp">
            <Show
              when={desc()}
              fallback={<p class="insp-none muted">{tekst('fill.unknown')}</p>}
            >
              <div class="fill">
                {/* VOLGORDE: boven het centrale vlak staat de UITWERKING, eronder
                    de GRONDSLAG — zo leest de keten van technisch naar juridisch.
                    Een leeg blok valt weg, label en al: de STAND van het vlak
                    volgt de keten zelf. */}
                <Show when={boven().length}>
                  <BlokRijen
                    blokken={boven()} scope={eigen()} cls="fill-up" dicht={!bovenOpen()}
                  />
                </Show>
                <div class="fill-cur">
                  <Show when={boven().length}>
                    <VouwRand
                      label={tekst('fill.up')} cls="fill-edge-up"
                      open={bovenOpen} zet={zetBovenOpen}
                    />
                  </Show>
                  <ul class="clean fill-list">
                    <Rij doel={s().ref} scope={eigen()} huidig />
                  </ul>
                  <Show when={herkomst().length}>
                    <p class="fill-origin muted">
                      {tekst('fill.origin', { sets: herkomst().join('; ') })}
                    </p>
                  </Show>
                  <Show when={onder().length}>
                    <VouwRand
                      label={tekst('fill.down')} cls="fill-edge-down"
                      open={onderOpen} zet={zetOnderOpen}
                    />
                  </Show>
                </div>
                <Show when={onder().length}>
                  <BlokRijen
                    blokken={onder()} scope={eigen()} cls="fill-down" dicht={!onderOpen()}
                  />
                </Show>
                {/* "Niet afgedwongen": eerlijke leegte, geen bevinding —
                    organisatorisch geborgd is een geldige stand van zaken. */}
                <Show when={ongedekt()}>{(u) => (
                  <div class="fill-block fill-off">
                    <p class="fill-head">{tekst('cov.notEnforcedHead')}</p>
                    <ul class="clean cov-conds">
                      <For each={u().ongedekt}>{(c) => (
                        <li
                          class={'cov-cond cov-cond-off muted'}
                          data-ref={c.iri} tabindex="0"
                          onMouseEnter={() => markeer(c.iri!, true, eigen())}
                          onMouseLeave={() => markeer(c.iri!, false, eigen())}
                        >
                          <VoorwaardeInhoud c={c} />
                          <Show when={c.label}><span class="c-note muted">{c.label}</span></Show>
                          <Show when={u().redenen[c.iri!] === 'not-enforced'}>
                            <span class="cov-not-enforced" title={tekst('cov.notEnforcedTitle')}>
                              {tekst('cov.notEnforced')}
                            </span>
                          </Show>
                          <Show when={u().redenen[c.iri!] === 'organisational'}>
                            <span class="cov-organisational muted" title={tekst('cov.organisationalTitle')}>
                              {tekst('cov.organisational')}
                            </span>
                          </Show>
                        </li>
                      )}</For>
                    </ul>
                  </div>
                )}</Show>
              </div>
            </Show>
          </div>
        </aside>
      )}</Show>
      {/* De randindicator: de bron staat buiten het scrollvenster. Hoveren
          scrollt bewust NIET (dat doet pas de →); dit is alleen de hint. */}
      <Show when={randHint()}>{(pos) => (
        <div class={'ref-edge ' + (pos() === 'above' ? 'edge-top' : 'edge-bottom')} aria-hidden="true">
          <span class="ref-edge-arrow">{pos() === 'above' ? '▲' : '▼'}</span>
        </div>
      )}</Show>
    </>
  );
}
