// HET BRONNENPANEEL: waar komt dit document vandaan, en wat doe je ermee?
//
// RECHTS EN NIET BOVEN sinds 9 sep 2026 (eigenaarsbesluit, letterlijk: "Sources
// is logischer als een pane aan de rechterzijde dan aan de top. Dan kan de 'add
// source' gewoon onder de gebruikelijke sources staan."). Het was een balk over
// de volle breedte onder de kop; het is nu een vaste kolom rechts, met de
// bronnen VERTICAAL onder elkaar.
//
// ÉÉN LIJST, IN ELKE STAND — herontwerp van diezelfde dag, eigenaar, letterlijk:
// "Eerst alleen een lijst van bronnen met een edit en x/delete icoontje ernaast
// en bron toevoegen met URL veld. Als je het edit icoontje klikt naast die bron
// wordt het direct editable en krijg je een revert icoontje en download
// icoontje."
//
// WAT DAARMEE VERVALT, en het is bewust:
//   * DE TWEE LIJSTEN. Er was een leesvorm (naam + slotjes-mededeling) en een
//     bewerkvorm (dezelfde rij als keuzegroep, met knoppen). Ze stonden apart
//     zodat de leeschunk niet zou groeien, en dat kostte precies wat zo'n
//     splitsing altijd kost: twee plekken die uit elkaar lopen. Nu is er één
//     lijst; de RIJ heeft twee standen (✎ ✕ tegenover ↶ ⤓ ✕), en die staan in
//     bronnen-acties.tsx.
//   * DE SLOTJES-MEDEDELING (`.src-slot`, "alleen-lezen"/"lokaal bewerkbaar").
//     Zij was leesinformatie zolang er geen knop naast stond; nu zeggen de
//     icoontjes hetzelfde en zou de tekst een tweede waarheid zijn. De
//     mededeling die WEL informatie draagt blijft staan: "(lokaal bewerkt)"
//     achter een bron die uit een kopie in deze browser komt.
//   * DE RADIOGROEP. Het één-bewerkbron-model (spec-addendum 6 sep) geldt
//     ONVERANDERD onder water — `maakBewerkbaar` zet de vorige bron vanzelf
//     terug op lezen — maar het is geen zichtbare keuze-uit-veel meer. Die vraag
//     wordt nu gesteld waar hij thuishoort: in de modal achter de bewerkknop, en
//     alleen als er iets te kiezen valt.
//
// Gedragsbron: renderSources in de bevroren viewer (viewer-bevroren/assets/doc.js) — de
// lijst met geladen bronnen, elke bron doorklikbaar naar het ruwe bestand, de
// foutmelding achter een bron die niet gelezen kon worden, de mededeling dat een
// bron uit een lokale kopie komt, het SPARQL-endpoint als eigen regel, en het
// veld "Bron toevoegen" eronder. Dat veld is bij de migratie nooit meegekomen en
// staat er met dit herontwerp weer.
//
// Knop en paneel zijn twee componenten met één gedeelde open/dicht-stand: de
// knop staat in de topbalk (doc.html, #btn-sources), het paneel hangt eraan via
// aria-controls. Sinds de verhuizing staat het paneel er niet meer ONDER maar
// NAAST; de knop blijft de schakelaar en houdt zijn aria-expanded.
import { createEffect, createSignal, For, onCleanup, Show } from 'solid-js';
import { bronnen, endpoint, fouten } from '../../stores/corpus.js';
// DE BRONNENLAAG STAAT AL IN DE LEESCHUNK (src/app.tsx importeert
// `startBronbeheer` statisch), dus dit kost de leesviewer geen byte extra.
import {
  bewerkbron, bijgeladenMelding, bronRijen, maakWerkbestand, opfsAan, voegBronToe,
} from '../../stores/bronbeheer.js';
import type { BronBewerk } from '../../stores/bronbeheer.js';
import { voorbeeldZoekstring } from '../../model/default-corpus.js';
import { tekst } from '../../stores/weergave.js';
import { veiligeHref } from '../gedeeld/veilige-link.js';
import { Bronacties, Endpointregel } from './bronnen-acties.jsx';
import './bronnen.css';

/** De fouten van de corpusstore op naam én op url — beide sleutels tellen. */
export function foutenTabel(
  fout: readonly { url?: string; name?: string; message: string }[],
): Map<string, string> {
  const opNaam = new Map<string, string>();
  for (const f of fout) {
    if (f.name) opNaam.set(f.name, f.message);
    if (f.url) opNaam.set(f.url, f.message);
  }
  return opNaam;
}

/** De NAAM van een bron: doorklikbaar naar het ruwe bestand als er een adres
 *  is, anders platte tekst — geen dode link. */
export function Bronnaam(props: { naam: string; url?: string }) {
  // HET ADRES KOMT UIT `?src=` EN IS DUS INVOER. Een bronadres met een
  // uitvoerbaar schema hoort de adresbalk niet meer te passeren (zie
  // `BRONSCHEMAS` in stores/corpus.ts), maar de bronnenlijst draagt ook namen
  // die langs andere wegen binnenkomen — en een link is de enige plek in dit
  // paneel waar een schema iets DOET. Dezelfde regel als op de kaarten:
  // onbruikbaar adres = tekst, niet weggepoetst.
  return (
    <Show when={veiligeHref(props.url)} fallback={<span class="src-naam">{props.naam}</span>}>
      {(u) => <a class="src-naam" href={u()} target="_blank" rel="noopener">{props.naam}</a>}
    </Show>
  );
}

/** Een knopje in het bronnenpaneel. GEEN emoji: die bestaat op een systeem
 *  zonder emoji-font als een leeg blokje, en dan is de enige aanwijzing wat een
 *  rij doet, weg. De tekens die hier gebruikt worden (✎ ↶ ⤓ ✕) zitten in de
 *  gewone tekstfonts. De volledige betekenis staat in title én aria-label. */
export function Srcknop(props: {
  klasse: string; label: string; titel: string; uit?: boolean;
  bij: () => void;
}) {
  return (
    <button
      type="button"
      class={props.klasse}
      title={props.titel}
      aria-label={props.titel}
      disabled={props.uit || undefined}
      onClick={() => { if (!props.uit) props.bij(); }}
    >{props.label}</button>
  );
}

/** De foutnoot achter een bron die niet gelezen kon worden.
 *
 *  EIGEN KLASSE, geen `src-err`. Die naam draagt in deze app óók de
 *  BLOK-foutmelding van de SPARQL-stand (kader, achtergrond, padding,
 *  `color: var(--fg)`) — twee verschillende dingen onder één naam, waarbij
 *  alleen de volgorde in de bundel besliste wie won. Deze noot is inline en
 *  gedempt, en zegt dat nu zelf. */
export function Bronfout(props: { fout?: string }) {
  return <Show when={props.fout}>{(m) => <span class="src-foutnoot">{' — ' + m()}</span>}</Show>;
}

// De open/dicht-stand van het paneel, gedeeld door knop en paneel. Dicht bij
// het opstarten, precies als #sources-panel[hidden] in de oude pagina.
const [bronnenOpen, zetBronnenOpen] = createSignal(false);
export { bronnenOpen, zetBronnenOpen };

/** De knop die het bronnenpaneel open- en dichtklapt. Hoort in de kop, naast de
 *  taalkiezer (in de oude pagina: #btn-sources in de topbalk). */
export function Bronnenknop() {
  return (
    <button
      class="btn bronnen-knop"
      id="btn-bronnen"
      type="button"
      aria-controls="bronnen-paneel"
      aria-expanded={bronnenOpen() ? 'true' : 'false'}
      onClick={() => zetBronnenOpen(!bronnenOpen())}
    >{tekst('src.toggle')}</button>
  );
}

/** BRON TOEVOEGEN OP ADRES. Het veld uit de bevroren viewer (doc.html,
 *  #form-add-src) dat bij de migratie nooit is meegekomen; de eigenaar vroeg
 *  hem terug: "bron toevoegen met URL veld".
 *
 *  ÉÉN VELD VOOR ALLE BRONSOORTEN, zoals daar: of dit een RDF-bestand of een
 *  SPARQL-endpoint is, zoekt de laadweg zelf uit (`detectSource` in de
 *  corpusstore). Wat hier gebeurt is dus niet "laden" maar "verklaren": het
 *  adres gaat de bronnenlijst in en de gewone lading doet de rest — inclusief
 *  de foutmelding als het adres niets bruikbaars oplevert. */
function Bronvelder() {
  const [adres, zetAdres] = createSignal('');
  // WAT ER MET DE LAATSTE TOEVOEGING GEBEURDE. Zonder deze twee is een adres dat
  // niet geladen kon worden een klik die niets doet: de rij komt er niet (een
  // mislukte lading levert geen bron op), dus zou de lezer alleen zien dat zijn
  // veld leeg werd.
  const [laatste, zetLaatste] = createSignal<string | null>(null);
  const [dubbel, zetDubbel] = createSignal<string | null>(null);
  const noot = () => {
    const d = dubbel();
    if (d) return tekst('src.alGeladen', { url: d });
    const u = laatste();
    if (!u) return null;
    const f = fouten().find((x) => x.url === u);
    return f ? tekst('src.toevoegFout', { url: u, fout: f.message }) : null;
  };
  const dien = (e: Event) => {
    e.preventDefault();
    const u = adres().trim();
    if (!u) return;
    zetAdres('');
    const uitkomst = voegBronToe(u);
    zetDubbel(uitkomst === 'dubbel' ? u : null);
    zetLaatste(uitkomst === 'toegevoegd' ? u : null);
  };
  return (
    <>
      <form class="bronnen-toevoegform" onSubmit={dien}>
        <input
          type="text"
          class="src-add-url"
          id="src-add-url"
          value={adres()}
          placeholder={tekst('src.placeholder')}
          aria-label={tekst('src.addLabel')}
          onInput={(e) => zetAdres(e.currentTarget.value)}
        />
        <button type="submit" class="btn src-add-ok">{tekst('src.addButton')}</button>
      </form>
      <Show when={noot()}>{(n) => <p class="src-toevoegnoot muted">{n()}</p>}</Show>
    </>
  );
}

/** Het paneel zelf: de geladen bronnen met hun acties, en eronder de manieren om
 *  er een bij te zetten. Een VASTE KOLOM RECHTS (eigenaarsbesluit 9 sep 2026);
 *  in de DOM staat hij tussen de kop en de hoofdkolom, want dat is de
 *  tabvolgorde die de lezer verwacht na de knop die hem opent. */
export function Bronnenpaneel(props: {
  /** De bewerkstand van het DOCUMENT. Het paneel zelf staat er in elke stand
   *  hetzelfde bij; deze vlag zet alleen de twee dingen die over documentbewerken
   *  gaan: de uitleg bij de bewerkbron en de noot dat er nog geen is. */
  bewerken?: () => boolean;
} = {}) {
  const bewerken = () => !!props.bewerken?.();
  const tabel = () => foutenTabel(fouten());
  const foutBij = (b: BronBewerk) =>
    tabel().get(b.name) ?? (b.url ? tabel().get(b.url) : undefined);
  // DE PSEUDO-BRONNEN VAN HET ENDPOINT (policylijst, eerste beeld, detail-
  // CONSTRUCTs) krijgen geen eigen regel: het endpoint staat al als eigen regel
  // onderaan, anders lijkt dezelfde bron dubbel te staan.
  //
  // DE VOCABULAIRE OOK NIET (9 sep 2026). Zij laadt automatisch mee zodra er een
  // eigen bron is; zij is niet gevraagd, niet te bewerken en niet te
  // verwijderen. In deze lijst zou zij de lege staat vervuilen — je opent de app,
  // hebt niets geladen en ziet twee bestanden staan die je niet kent. Zij staat
  // wél onderaan het paneel, want "waar komt dit vandaan" is de vraag die dit
  // paneel beantwoordt, en stilzwijgend twee bestanden laden is daar geen
  // antwoord op.
  const rijen = () => bronRijen().filter((b) => !b.fromSparql && !b.vocab);
  const vocabRijen = () => bronRijen().filter((b) => !b.fromSparql && b.vocab);
  const leeg = () => !rijen().length && !endpoint();

  // DE BODYKLASSE die de leeskolom vrijhoudt. Hier en niet in de knop, want zij
  // hoort bij de STAND van het paneel: ook `?edit=1` en de aanbod-route
  // (schakelBewerkstand) zetten hem open zonder dat er op de knop geklikt is.
  // Bij unmount weer weg — anders houdt een afgebroken render de pagina
  // permanent 320px smal.
  createEffect(() => {
    const b = typeof document === 'undefined' ? null : document.body;
    if (b) b.classList.toggle('bronnen-open', bronnenOpen());
  });
  onCleanup(() => {
    if (typeof document !== 'undefined') document.body.classList.remove('bronnen-open');
  });

  /** Sluiten met de focus mee. Stond de focus IN het paneel, dan verdwijnt hij
   *  met het paneel; hij hoort dan terug naar de knop die het paneel opende —
   *  dezelfde regel als `focusVolgt` in de zijnav. Stond hij ergens anders in
   *  het document, dan blijft hij daar: een sprong naar de kop vroeg niemand. */
  function sluitPaneel(focusVolgt: boolean): void {
    zetBronnenOpen(false);
    if (!focusVolgt || typeof document === 'undefined') return;
    (document.getElementById('btn-bronnen') as HTMLElement | null)?.focus();
  }

  // --- De Escape-laag ---------------------------------------------------------
  // FIXRONDE 9 sep 2026 (review-bronnenpaneel): dit paneel sloot niet op Escape,
  // terwijl de zijnav en het invulling-paneel dat allebei doen. Voor wie met het
  // toetsenbord werkt is dat een gat in een geleerde reflex.
  //
  // IN DE CAPTURE-FASE, om dezelfde reden als bij het invulling-paneel: de
  // zijnav luistert in de BUBBELfase op het document, en zonder capture zou één
  // Escape dit paneel én de zijnav sluiten. Capture draait vóór elke
  // bubbel-luisteraar, dus deze laag kan de toets opmaken en met
  // `stopImmediatePropagation` tegenhouden dat de zijnav hem óók krijgt.
  //
  // VIER UITZONDERINGEN, elk een laag die BOVEN deze ligt. Ze staan hier en niet
  // bij die lagen zelf, omdat capture-op-het-document nu eenmaal vóór hen draait
  // en zij zich dus niet kunnen verdedigen:
  //   1. DE BRONKIEZER-MODAL (body.bronkiezer-open). Een modale dialoog is per
  //      definitie de bovenste laag. Zij luistert zelf ook in capture en is
  //      eerder geregistreerd (Bewerkchrome mount vóór dit paneel), maar de
  //      klasse maakt de regel leesbaar in plaats van afhankelijk van
  //      mountvolgorde.
  //   2. HET INVULLING-PANEEL (body.panel-open). Dat opent vanuit een kaart en
  //      is daarmee de vluchtiger laag; dit paneel is chrome. De klasse is de
  //      bestaande naad tussen de twee (bronnen.css leest hem al om de panelen
  //      naast elkaar te zetten); een import zou de leeschunk aan ui/kaart
  //      hangen.
  //   3. EEN OPEN VELD (input/textarea/contentEditable) — letterlijk dezelfde
  //      uitzondering als invulling.tsx maakt. De Escape van een openstaand veld
  //      is van dat veld; hem inpikken zou een bewerking stil afbreken. Het geldt
  //      ook voor het URL-veld van dit paneel zelf.
  //   4. EEN OPEN MENU IN HET PANEEL (het downloadmenu). Dat sluit met Escape
  //      zijn eigen menu via een `on:keydown` op het element, en de targetfase
  //      komt ná capture. Op de attributen en niet op de focus, zodat de regel
  //      ook geldt voor een menu dat met de muis is opengeklapt.
  // De sleeplaag (zijnav-breedte) hoeft hier niet genoemd: die luistert óók in
  // capture, is als eerste geregistreerd (Zijnav mount vóór dit paneel) en stopt
  // de toets meteen.
  function opToets(e: KeyboardEvent): void {
    if (e.key !== 'Escape' || !bronnenOpen() || typeof document === 'undefined') return;
    const klassen = document.body?.classList;
    if (klassen?.contains('bronkiezer-open') || klassen?.contains('panel-open')) return;
    const a = document.activeElement as HTMLElement | null;
    const tag = String((a && a.tagName) || '').toLowerCase();
    if (tag === 'input' || tag === 'textarea' || a?.isContentEditable) return;
    const paneel = document.getElementById('bronnen-paneel');
    if (paneel?.querySelector('[aria-haspopup="menu"][aria-expanded="true"]')) return;
    sluitPaneel(!!(paneel && a && paneel.contains(a)));
    e.preventDefault();
    if (e.stopImmediatePropagation) e.stopImmediatePropagation();
    else e.stopPropagation();
  }
  if (typeof document !== 'undefined' && document.addEventListener) {
    document.addEventListener('keydown', opToets, true);
    onCleanup(() => document.removeEventListener('keydown', opToets, true));
  }

  return (
    <aside
      class="bronnen-paneel"
      id="bronnen-paneel"
      hidden={!bronnenOpen()}
      data-bewerken={bewerken() ? '1' : undefined}
      aria-labelledby="label-bronnen"
    >
      <div class="bronnen-kop">
        <h2 class="bronnen-label" id="label-bronnen">{tekst('src.loaded')}</h2>
        {/* EIGEN SLUITKNOP. De paginakop scrollt weg, dit paneel niet; zonder
            deze knop moet de lezer eerst terug naar boven om #btn-bronnen te
            vinden. Dezelfde rol als .tree-close aan de andere kant. */}
        <button
          class="bronnen-sluit"
          id="btn-bronnen-sluit"
          type="button"
          title={tekst('src.sluit')}
          aria-label={tekst('src.sluit')}
          onClick={() => sluitPaneel(true)}
        >✕</button>
      </div>
      <div class="bronnen-body">
        {/* DE UITLEG BIJ DE BEWERKBRON. Alleen in de bewerkstand: dat is de enige
            plek waar het uitmaakt dat alles wat je typt naar die ene bron gaat.
            Buiten de bewerkstand valt er niets te typen en zou de zin een vraag
            beantwoorden die niemand stelde. */}
        <Show when={bewerken()}>
          <p class="bronnen-uitleg muted">{tekst('src.bewerkbronPaneel')}</p>
        </Show>
        <ul class="bronnen-lijst" id="bronnen-lijst" aria-labelledby="label-bronnen">
          <For each={rijen()}>{(b) => (
            <li
              class={foutBij(b) ? 'src-error-li' : undefined}
              data-bron={b.name}
              data-modus={b.modus}
              data-graph={b.graph}
            >
              <Bronnaam naam={b.name} url={b.url} />
              {/* DE ENIGE STANDMEDEDELING DIE BLIJFT. "(lokaal bewerkt)" zegt
                  iets dat de icoontjes niet zeggen: de INHOUD komt uit een kopie
                  in deze browser, ook als deze bron nu niet de bewerkbron is.
                  Zonder haar zou de lezer denken naar het origineel te kijken. */}
              <Show when={b.opfs}>
                <span class="src-lokaal" title={tekst('src.lokaalUitleg')}>
                  {' ' + tekst('src.lokaal')}
                </span>
              </Show>
              {' '}
              <Bronacties bron={b} fout={foutBij(b)} />
              <Bronfout fout={foutBij(b)} />
            </li>
          )}</For>
          <Endpointregel />
        </ul>
        {/* DE LEGE STAND, ALS LIVE REGION. `role="status"` is het aria-live-
            patroon voor een beleefde mededeling (het impliceert
            `aria-live="polite"` en `aria-atomic="true"`), en dat hoort hier: de
            lijst kan onder je handen leeglopen — een ✕ op de laatste bron, een
            corpus dat niets oplevert — en zonder aankondiging blijft een
            schermlezer bij een lijst staan die er niet meer is.
            HET ELEMENT STAAT ER ALTIJD, en alleen zijn TEKST komt en gaat. Een
            live region die pas mét zijn mededeling in de DOM verschijnt wordt
            door een deel van de schermlezers niet voorgelezen: de regio moet er
            al zijn vóór hij verandert. Zonder tekst is de <p> leeg en neemt hij
            geen ruimte (zie `.bronnen-leeg:not([data-leeg])` in bronnen.css). */}
        <p
          class="bronnen-leeg muted"
          role="status"
          data-leeg={leeg() ? '1' : undefined}
        >
          <Show when={leeg()}>
            {tekst('src.geenBronnen')}
            {' '}
            {/* HET VOORBEELDLINKJE — een HANDREIKING, geen automatische lading.
                De demobronnen laden sinds 9 sep 2026 niet meer vanzelf
                (eigenaar: "demobronnen moeten eruit"), maar ze bestaan nog en
                zijn het snelste antwoord op "hoe ziet dit eruit met data".
                EEN ECHTE LINK EN GEEN KNOP, en dat is de ruling: wat hij doet is
                naar een ANDER ADRES gaan — precies het adres dat de lezer ook
                zelf had kunnen typen. Daarmee is hij te kopiëren, te delen, in
                een nieuw tabblad te openen en met de terugknop ongedaan te
                maken; een knop met een klikafhandeling zou dat alles zelf moeten
                nabouwen. */}
            <a class="src-voorbeelden" href={voorbeeldZoekstring()}>{tekst('src.voorbeelden')}</a>
          </Show>
        </p>

        {/* HET BIJGELADEN ENDPOINTMATERIAAL (de dt2-reviewerwens). De
            knoop-CONSTRUCTs van de verkenner, de collectieniveaus en de
            kaartdetails staan in de graaf onder de graph van het ENDPOINT en
            horen bij geen enkele bron. Ze gaan dus niet mee in een werkbestand of
            in de download van een bron — precies het soort stil verlies waar een
            lezer pas achterkomt als hij zijn bestand opent. */}
        <Show when={bijgeladenMelding()}>{(m) => (
          <p class="muted src-bijgeladen">{tekst('src.bijgeladenKort', { n: m().n })}</p>
        )}</Show>

        {/* BRON TOEVOEGEN, DIRECT ONDER DE LIJST EN IN ELKE STAND.
            Eigenaarsbesluit 9 sep 2026 ("Dan kan de 'add source' gewoon onder de
            gebruikelijke sources staan") plus de bevinding van diezelfde dag,
            letterlijk: "Nu kan ik helemaal geen bron meer toevoegen" — gezegd in
            kijkstand. Een corpus samenstellen is leeswerk: je bepaalt ermee wát
            je leest. Twee manieren, zoals in de bevroren viewer: een ADRES
            (bestand of endpoint) en een leeg WERKBESTAND in deze browser. */}
        <h3 class="bronnen-label bronnen-toevoeg-label" id="label-bron-toevoegen">
          {tekst('src.addLabel')}
        </h3>
        <Bronvelder />
        <ul class="bronnen-gereedschap" aria-labelledby="label-bron-toevoegen">
          <li class="src-gereedschap">
            <Srcknop
              klasse="src-werkbestand"
              label={tekst('src.werkbestand')}
              titel={opfsAan() ? tekst('src.werkbestandUitleg') : tekst('src.opfsUit')}
              uit={!opfsAan()}
              bij={() => void maakWerkbestand()}
            />
            {' '}
            {/* Zonder bewerkbron kan er niets bewaard worden. Alleen in de
                bewerkstand: buiten die stand valt er niets te bewaren en zou de
                noot een probleem melden dat er niet is. */}
            <Show when={bewerken() && !bewerkbron() && rijen().length}>
              <span class="src-geen-bewerkbron">{tekst('src.geenBewerkbron')}</span>
            </Show>
          </li>
        </ul>

        {/* DE ONDERSTEUNENDE BRONNEN, als eigen categorie onderaan. Ze dragen
            geen acties: ze zijn niet van de lezer, hij heeft ze niet gevraagd en
            hij kan ze niet kwijt — bewerken of verwijderen zou een affordance
            zijn die de app meteen weer ongedaan maakt. Wat hij wél kan is erop
            doorklikken, en dat is precies wat een bron in dit paneel te bieden
            heeft. */}
        <Show when={vocabRijen().length}>
          <h3 class="bronnen-label bronnen-vocab-label" id="label-vocabulaire">
            {tekst('src.vocabulaire')}
          </h3>
          <ul class="bronnen-lijst bronnen-vocab" aria-labelledby="label-vocabulaire">
            <For each={vocabRijen()}>{(b) => (
              <li data-bron={b.name} data-vocab="1" data-modus={b.modus}>
                <Bronnaam naam={b.name} url={b.url} />
                <Bronfout fout={foutBij(b)} />
              </li>
            )}</For>
          </ul>
          <p class="bronnen-vocab-uitleg muted">{tekst('src.vocabulaireUitleg')}</p>
        </Show>
      </div>
    </aside>
  );
}
