// HET MOUNTPUNT VAN DE BEWERKLAAG — de enige module die de leeschunk en de
// bewerkchunk delen.
//
// DE HARDE EIS (spec §1): de leesviewer laadt geen byte bewerkcode. Dat is niet
// af te dwingen met een `Show when={editMode}`: een STATISCHE import van een
// bewerkcomponent trekt hem hoe dan ook de instapchunk in, hoe goed hij ook
// verborgen wordt. De grens moet dus een module-grens zijn, en dan is er precies
// één vorm die werkt: de leeskant kent alleen een SIGNAAL met functies erin, en
// de bewerkchunk vult dat signaal wanneer hij geladen is.
//
// Vandaar dit bestand. Het importeert niets uit `stores/bewerk.ts`, niets uit
// `model/edit.js` en niets uit `ui/bewerk/` — alleen solid-js, typen en
// `stores/weergave.js`. Die laatste is de UITZONDERING die de kijkstand-poort
// hieronder nodig heeft, en zij kost de instap geen byte: de leeskant laadt die
// store zelf al eager (de hele viewer hangt eraan). `stores/lazy-grens.test.ts`
// houdt die twee dingen vast — welke module een mountpunt IS en welke vorm zij
// moet dragen. Wie er iets aan toevoegt, controleert dat opnieuw: één import
// naar de bewerklaag hier haalt de hele laag de instap in, en de bewaker vangt
// alleen de directe verwijzingen naar de mutatiekern.
//
// WIE VULT HET: `ui/bewerk/laag.tsx`, op importmoment. Die module is het
// dynamische-import-doel van de bewerkchrome (`ui/app/bewerkstand.tsx`) en de
// wortel van de bewerkchunk. De andere golf B-lanes (ghost-integratie,
// formulieren, slepen) hangen hun eigen haken aan ditzelfde signaal — zie
// `Kaarthaken` hieronder; een lane die er een veld bij zet, zet hem hier bij en
// vult hem in `laag.tsx`.
import { Show, createSignal } from 'solid-js';
import type { JSX } from 'solid-js';
import { weergave } from '../../stores/weergave.js';

/** WAT VOOR VELD dit is. `datum` is een `tekst`-veld met een datumwidget en
 *  xsd:date als standaardvorm; het staat er apart in omdat de aanroeper die
 *  keuze maakt (de weergave weet dat dct:issued een datum is) en niet de
 *  bewerklaag. */
export type VeldSoort = 'tekst' | 'datum' | 'iri';

// DE PREDICATEN DIE DE KAARTVELDEN DRAGEN, als kale strings.
//
// Ze staan HIER en niet in `model/velden.js`, om precies één reden: de
// leeskant heeft ze nodig (elke `VeldSpec` draagt er een) en `model/velden.js`
// importeert `model/edit.js`. Eén import daarheen vanuit `kaart.tsx` zou de
// hele serialisatielaag (13,6 kB) de leeschunk in trekken — de fout die de
// lazy-grens juist moet voorkomen.
//
// De modellaag houdt daarom zijn EIGEN kopie (`TITEL_PREDS`/`TOELICHT_PREDS` in
// `model/velden.js`), en `haken.test.tsx` pint de twee aan elkaar vast: een
// test die beide kant en klaar mag importeren, want een testbestand zit in geen
// enkele chunk.
const DCT = 'http://purl.org/dc/terms/';
const ODRL = 'http://www.w3.org/ns/odrl/2/';
const RDFS = 'http://www.w3.org/2000/01/rdf-schema#';
const SKOS = 'http://www.w3.org/2004/02/skos/core#';

export const PRED = {
  /** Een titel is dct:title óf rdfs:label — in die voorkeursvolgorde. */
  TITEL: [DCT + 'title', RDFS + 'label'],
  /** DE NAAM VAN EEN KNOOP DIE ALLEEN ALS LABEL GETOOND WORDT — de waarde van
   *  een groepeerdimensie (het doel boven een doelgroep-vakje), waar geen
   *  kaartkop en geen dct:title-cultuur omheen staat.
   *
   *  ANDERE VOLGORDE DAN `TITEL`, en dat is de hele reden dat hij apart staat:
   *  `labelFor`/`ownLabel` in `model/parse.js` leest rdfs:label, dan
   *  skos:prefLabel, dan dct:title, en `dragendPred` kiest het predicaat dat de
   *  knoop AL draagt. Met `TITEL` zou een doelknoop met zowel rdfs:label als
   *  dct:title zijn dct:title bewerkt krijgen terwijl de kop zijn rdfs:label
   *  toont — een save die niets zichtbaars doet. Deze ladder is dezelfde als die
   *  van de weergave, dus het bewerkte predicaat is per definitie het predicaat
   *  dat de getoonde naam levert (eigenaarsbevinding 9 sep 2026: "Ik kan de naam
   *  van het doel nu helemaal nergens editen"). */
  NAAM: [RDFS + 'label', SKOS + 'prefLabel', DCT + 'title'],
  /** Een toelichting is dct:description óf rdfs:comment. */
  TOELICHT: [DCT + 'description', RDFS + 'comment'],
  ASSIGNER: [ODRL + 'assigner'],
  ASSIGNEE: [ODRL + 'assignee'],
  ISSUED: [DCT + 'issued'],
  IDENTIFIER: [DCT + 'identifier'],
} as const;

/** ÉÉN BEWERKBAAR VELD, zoals de LEESKANT hem beschrijft.
 *
 *  De leeskant zegt WELKE knoop, WELK predicaat en WAT er nu staat; hij zegt
 *  niet of het veld bewerkbaar is, want dat is een uitspraak over de bewerkbron
 *  en die kent hij niet. Die toets doet de bewerklaag (`ui/bewerk/kaartveld.tsx`
 *  met `quadsInBewerkbron` uit de mutatiekern). */
export interface VeldSpec {
  /** De knoop waarop dit veld staat: een IRI of een term uit de graaf. */
  term: unknown;
  soort: VeldSoort;
  /** De VOORKEURSVOLGORDE van dragende predicaten (een titel is dct:title óf
   *  rdfs:label). De bewerklaag kiest het predicaat dat de knoop al draagt; is
   *  er maar één kandidaat, dan is dit een lijst van één. */
  preds: readonly string[];
  /** NIET VAN TOEPASSING, met de reden. De leeskant weet soms zelf al dat dit
   *  veld niet als één waarde te bewerken is (een rij met meer dan één waarde,
   *  een samengestelde knoop, een afnemer die op de regel staat en niet op de
   *  kaart). Dan verdwijnt het ✎ niet — het staat er gedimd bij met deze zin,
   *  precies zoals de actiestrook een icoon nooit verbergt maar uitzet met zijn
   *  reden. Een raadselachtig ontbrekend potlood is erger dan een grijs
   *  potlood dat zegt waarom. */
  nvt?: string;
  /** De getoonde tekstwaarde (soort 'tekst'/'datum'), leeg als het veld er nog
   *  niet is. */
  waarde?: string | null;
  /** De huidige IRI (soort 'iri'), of null. */
  iri?: string | null;
  /** De optiecategorie van de combobox (`termOptions`-sleutel: parties,
   *  targets, actions, …). */
  categorie?: string;
  /** DE HINT VAN EEN LEEG VELD — het `placeholder`-attribuut, niet de waarde.
   *
   *  Eigenaarsbevinding 9 sep 2026, letterlijk: "Placeholders als (vul
   *  aanbieder in) op allerlei plekken zijn echt tekst in het invoerveld i.p.v.
   *  subtle hints die verdwijnen als je begint te typen." Het skelet schreef die
   *  teksten als rdfs:label in de GRAAF; ze staan nu waar ze horen — op het
   *  invoerveld, waar de browser ze zelf weghaalt bij de eerste toetsaanslag.
   *  Leeg laten betekent: de algemene hint van het widget (`edit.iriPlaceholder`
   *  bij een combobox). */
  hint?: string;
  /** DE ROUTE NAAR EEN NIEUWE GROEP (eigenaarsbevinding 9 sep 2026: "Als hij er
   *  wel een heeft is een PartyCollection met refinements ook niet aan te
   *  maken").
   *
   *  Een afnemer of aanbieder hoeft geen enkele partij te zijn: het
   *  één-bewerkbron-/V14-spoor staat een `odrl:PartyCollection` met een
   *  afbakening toe, en de LEESkant toont die al (de collectiekaart met haar
   *  "Afbakening"-sectie). Er was alleen geen AANMAAKroute — een groep bestaat
   *  pas nadat iemand hem in de bron typte.
   *
   *  Deze vlag zegt dat dit veld een PARTIJ aanwijst en dus die tweede route
   *  verdient; de bewerklaag hangt er een "+ groep"-knop naast (`IriVeld` in
   *  `ui/bewerk/kaartveld.tsx`). Hij staat hier en niet als afleiding uit
   *  `categorie === 'parties'`, omdat "waar komen de suggesties vandaan" en
   *  "mag hier een groep ontstaan" twee verschillende vragen zijn: een
   *  invulling-paneel dat ooit partij-suggesties toont, hoort daarmee nog geen
   *  mint-knop te krijgen. */
  nieuweGroep?: boolean;
  meerregelig?: boolean;
  /** Geen ✎ vlak achter de waarde: de rij draagt er één in haar actiestrook. */
  zonderPotlood?: boolean;
  /** DE NAAM VAN HET VELD, voor een melding die erover gaat. `body-rijen.tsx`
   *  vult hem uit de stringtabel of uit het predicaatlabel in de graaf. */
  label?: string;
  /** HET ADRES WAAROP DIT VELD DE CURSOR AANNEEMT (eigenaarsbesluit 8 sep 2026:
   *  na een toevoeging springt de bewerkstand naar het nieuwe element). Komt het
   *  overeen met `bewerkFocus()` uit `ui/gedeeld/bewerkhaak.tsx`, dan opent dit
   *  veld zichzelf en zet het de cursor erin. De leeskant vult hem met
   *  `focusAdres(term)`; de ghost die de knoop maakte zette datzelfde adres.
   *
   *  Alleen op velden die een element BENOEMEN (de titel van een kaart, de naam
   *  van een regelrij): het besluit zegt "titel editable at least", en een
   *  tweede veld dat zich op hetzelfde adres herkent zou om de cursor vechten. */
  focusSleutel?: string;
  /** WELKE MUTATIE dit veld schrijft, als dat niet de kale `setIri` op
   *  (term, pred) is. De LEESkant benoemt hier de betekenis; de bewerklaag kent
   *  de bijbehorende functie in `model/edit.js`. Vandaag één waarde:
   *
   *   - `'actie'` — de odrl:action van een regel. Die staat in de ODRL-AP-NL-vorm
   *     als `[ rdf:value <actie> ]`, met de doelbinding en de andere refinements
   *     eraan; een kale `setIri` zou die blanke knoop vervangen door een directe
   *     IRI en de refinements laten vallen. `setAction` behoudt de structuur;
   *   - `'knoopIri'` — de IRI VAN DE KNOOP ZELF, niet een waarde erop
   *     (eigenaarsverzoek 9 sep 2026: "Ik kan de node-id niet editen"). Er is
   *     hier geen `preds`: een IRI is de NAAM van de knoop en staat in élke
   *     triple waarin hij voorkomt. De mutatie is `hernoemKnoop`, die alle
   *     posities tegelijk verzet; de reden staat daar voluit. Dit veld toont
   *     zich ALLEEN in de bewerkstand — de bevroren viewer draagt geen IRI-chip
   *     op de kaartkop, en de leesweergave hoort er geen pixel van te merken. */
  vorm?: 'actie' | 'knoopIri';
  // GEEN `patroon` MEER (review I-5). Er stond hier `patroon?: string` naast,
  // met het bijschrift "alleen de formulierrijen (lane-formulieren) vullen deze
  // twee". Dat klopte niet: de formulierrijen lopen over `FormRij` en niet over
  // `VeldSpec`, dus NIEMAND vulde hem — de poort die hem in `kaartveld.tsx` las
  // was onbereikbaar en ongetoetst, en is bij de fixronde weggehaald. Een veld
  // dat niemand schrijft en niemand leest is erger dan geen veld: het nodigt de
  // volgende lane uit om iets te zetten waar niets mee gebeurt. (`label` blijft
  // wél staan: die wordt op twee plekken echt gevuld.)
  //
  // Terug te zetten zodra er een kaartrij MET een shape-patroon is — samen met
  // een producent, `patroonPoort` uit `ui/kaart/formulier-bewerk.tsx` en een
  // test per tak.
}

/** De haken die de bewerklaag aanbiedt zodra zij geladen is. Elke lane van golf
 *  B zet hier zijn eigen ingang bij; `veld` is die van lane-velden. */
export interface Kaarthaken {
  /** De bewerkbare vorm van één veld, of de leesvorm als dit veld in deze stand
   *  niet te bewerken is (kijkstand, geen bewerkbron, andere bron). */
  veld: (spec: VeldSpec, lees: () => JSX.Element) => JSX.Element;
}

const [kaarthaken, zetKaarthaken] = createSignal<Kaarthaken | null>(null);

/** VRAAGT DE BEWERKLAAG OM EEN BEWERKBRON? (het aanbod staat open).
 *
 *  De vlag zelf woont in de mutatiekern (`aanbodOpen`), maar de LEESKANT moet
 *  hem kunnen lezen: het bronnenpaneel toont zijn keuzegroep alleen in de
 *  bewerkvorm, en die stand is er zonder bewerkbron juist niet — zonder deze
 *  vlag wijst het aanbod dus naar een paneel dat op dat moment niets te kiezen
 *  geeft.
 *
 *  HIJ STAAT HIER en niet in `ui/app/bewerkstand.tsx`, om een reden die alleen
 *  in de gebouwde bundel zichtbaar is: als de bewerkchunk iets uit
 *  `bewerkstand.tsx` importeert, ontstaat er een lus (entry → import() → chunk →
 *  entry) en knipt Rollup de instap in drie losse chunks. Gemeten: de leeschunk
 *  viel dan uiteen in index/parse/bronbeheer met drie modulepreloads in plaats
 *  van één script. Dit bestand is al de gedeelde grond van beide kanten en
 *  importeert niets zwaars; een signaal erbij kost geen byte extra. */
const [bronkeuze, zetBronkeuze] = createSignal(false);

export { bronkeuze, kaarthaken, zetBronkeuze, zetKaarthaken };

/** EEN VELD IN DE WEERGAVE. In de leesstand — en zolang de bewerklaag niet
 *  geladen is — rendert hij letterlijk zijn `children`, dus de leesviewer
 *  verandert er geen pixel van. Is de laag er, dan beslist zij.
 *
 *  De leesnode staat in `children` en niet in een prop, zodat de bestaande
 *  weergavecode ongewijzigd blijft staan: er komt een omhulsel omheen, er wordt
 *  niets herschreven. */
export function Veld(props: { spec: VeldSpec; children?: JSX.Element }): JSX.Element {
  return (
    // DE BEWERKSTAND MOET AAN STAAN, niet alleen de haak gevuld zijn — precies
    // de poort die `Haak` in `ui/gedeeld/bewerkhaak.tsx` draagt, en om precies
    // dezelfde reden (review I-1).
    //
    // Tot de verzoening van golf B vielen "haak gevuld" en "bewerkstand aan"
    // samen, want de lader van de ghost-integratie haalde de laag pas op bij
    // `editMode && bewerkbron`. Sinds de bewerkchrome van deze lane de énige
    // lader is, geldt dat niet meer: `?edit=1` op een corpus ZONDER bewerkbron
    // laadt de laag wél (het AANBOD om een bewerkbron te kiezen zit erin),
    // waarna `bevestigEditMode` de stand terecht weer uitzet. De haken bleven
    // dan gevuld — gemeten aan de `Haak`-kant: 60 actiestroken en 180 knoppen
    // op een pagina in de KIJKstand.
    //
    // WAAROM HIER EN NIET ALLEEN IN `KaartVeld`. Vandaag brengt de énige
    // implementatie van `Kaarthaken.veld` haar eigen poort mee, dus vandaag is
    // dit dubbel. Maar dan ligt de invariant "geen affordance in de kijkstand"
    // op twee hoogtes — bij `Haak` centraal, bij `Kaarthaken` per implementatie
    // — en de volgende lane die hier een haak bij zet, zet er een zonder poort.
    // De poort hoort bij het SIGNAAL, niet bij zijn invullers. `KaartVeld` houdt
    // de zijne: die draagt de pariteit-tests met de leesvorm.
    //
    // Dit is een fout die de lazy-grens per definitie niet vangt: er is geen
    // byte te veel geladen, hij wordt alleen getoond op het verkeerde moment.
    <Show when={weergave.editMode && kaarthaken()} fallback={props.children}>
      {(h) => h().veld(props.spec, () => props.children)}
    </Show>
  );
}
